<svg class="glass-art" viewBox="0 0 740 250" preserveAspectRatio="xMidYMid meet" aria-hidden="true"><defs><linearGradient id="glass-blue" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#658894" stop-opacity=".8"/><stop offset="1" stop-color="#355e68" stop-opacity=".08"/></linearGradient><linearGradient id="glass-rose" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#a4869a" stop-opacity=".6"/><stop offset="1" stop-color="#5d5573" stop-opacity=".05"/></linearGradient></defs><g fill="none" stroke="#ab9d74" stroke-width=".8"><path d="M245 242V121Q245 48 370 10Q495 48 495 121V242"/><path d="M255 240V122Q255 59 370 22Q485 59 485 122V240" opacity=".55"/><path d="M105 241V145Q105 105 173 76Q240 105 240 145V241M500 241V145Q500 105 567 76Q635 105 635 145V241" opacity=".45"/><path d="M123 239V149Q123 121 173 95Q223 121 223 149V239M517 239V149Q517 121 567 95Q617 121 617 149V239" opacity=".3"/></g><path d="M259 238V124Q259 65 370 29Q481 65 481 124V238Z" fill="url(#glass-blue)"/><path d="M128 238V150Q128 123 173 101Q218 123 218 150V238Z" fill="url(#glass-rose)"/><path d="M522 238V150Q522 123 567 101Q612 123 612 150V238Z" fill="url(#glass-rose)"/><g fill="none" stroke="#b0aa83" stroke-width=".7" opacity=".7"><circle cx="370" cy="134" r="86"/><circle cx="370" cy="134" r="72"/><path d="M370 29V58M370 210V242M285 134H255M455 134H484M310 73L291 54M430 73L450 54M308 195L290 215M432 195L451 215"/><path d="M370 37L339 82L370 65L401 82ZM280 127L316 103L298 134L316 165ZM460 127L424 103L442 134L424 165Z" fill="#b39f702a"/><path d="M173 104V237M128 166H218M567 104V237M522 166H612" opacity=".45"/></g><g fill="#c8b68b"><path d="M370 2L373 10L370 18L367 10Z"/><path d="M70 132L73 140L70 148L67 140Z"/><path d="M670 132L673 140L670 148L667 140Z"/><circle cx="315" cy="40" r="1.5"/><circle cx="425" cy="40" r="1.5"/><circle cx="290" cy="220" r="1.5"/><circle cx="450" cy="220" r="1.5"/></g><path d="M20 242H720" stroke="#a99d7644" stroke-width=".8"/></svg>
<div class="dial"><small>DAY</small><strong>…</strong><span>午后 · 秋晴</span></div></div><div class="obs-title"><h2></h2><p></p></div>
<div class="coordinates"><div><small>时间</small>2026.10.16 · 16:40</div><div><small>坐标</small>校园图书馆 · 靠窗座位</div><div><small>天候</small>秋晴，有风</div></div><details><summary class="wx-header-cast-toggle"><span>星图中的人</span><span class="dim">Char1 · Char2</span></summary><div class="cast-list"></div></details>
</div></div><script>(() => {
  'use strict';
  const template = document.getElementById('wx-header-source');
  const root = document.getElementById('wx-header-root');
  if (!template || !root) return;
  const text = template.content.textContent || '';
  const field = name => {
    const match = text.match(new RegExp('^\\s*\\[' + name + '\\s*[|｜:：]\\s*([^\\r\\n]*?)\\]\\s*$', 'mi'));
    return match ? match[1].trim() : '';
  };
  const lines = text.split(/\r?\n/).map(line => line.trim()).filter(Boolean);
  const oldTime = lines.find(line => line.includes('|') && !line.startsWith('[') && !line.startsWith('🎭')) || '';
  const oldParts = oldTime.split('|');
  const oldLocation = (oldParts[1] || '').split(/[·•]/).map(x => x.trim()).filter(Boolean);
  const dayText = field('DAY') || (text.match(/\bDAY\s*(\d+)/i) || [])[1] || '';
  const dayNumber = dayText.match(/\d+/);
  const data = {
    day: dayNumber ? dayNumber[0] : '未标注',
    time: field('时间') || (oldParts[0] || '').replace(/^📅\s*/, '') || '时间未标注',
    location: field('地点') || oldLocation.slice(2).join(' · ') || '地点未标注',
    weather: field('天气') || oldLocation[1] || '天气未标注',
    title: field('标题') || '此刻',
    note: field('题记'),
  };
  data.clock = (data.time.match(/\d{1,2}[:：]\d{2}/) || [])[0] || data.time;
  data.date = (data.time.match(/\d{4}[年.\/-]\d{1,2}[月.\/-]\d{1,2}日?/) || [])[0] || data.time;
  data.period = (data.time.match(/凌晨|清晨|早晨|上午|正午|午后|下午|傍晚|黄昏|深夜|夜间|夜晚|子时|丑时|寅时|卯时|辰时|巳时|午时|未时|申时|酉时|戌时|亥时/) || [])[0] || '';
  const casts = [];
  const wrapped = template.content.querySelectorAll('.ds-char');
  if (wrapped.length) {
    for (const entry of wrapped) {
      casts.push({
        name: (entry.querySelector('.ds-char-name')?.textContent || '').replace(/^🎭\s*/, '').trim(),
        affinity: entry.querySelector('.ds-char-affinity')?.textContent || '',
        identity: (entry.querySelector('.ds-char-row')?.textContent || '').split('|')[0].replace(/[\[\]]/g, ''),
        bond: entry.querySelectorAll('.ds-char-row')[1]?.textContent || '',
      });
    }
  } else {
    const castText = template.content.querySelector('cast')?.textContent || text;
    for (const line of castText.split(/\r?\n/)) {
      const name = line.match(/^\s*🎭\s*([^\[\n]+?)(?=\s*\[|$)/);
      if (!name) continue;
      const affinity = (line.match(/\[([^\]]*)\]/) || [])[1] || '';
      const identity = (line.match(/\[(?:身份|面具)[：:]\s*([^\]|]*)[^\]]*\]/) || [])[1] || '';
      const bond = (line.match(/\[羁绊暗流[：:]\s*([^\]]*)\]/) || [])[1] || '';
      casts.push({ name: name[1].trim(), affinity, identity, bond });
    }
  }
  const set = (selector, value) => {
    const node = root.querySelector(selector);
    if (node) node.textContent = value;
  };
  const note = selector => {
    set(selector, data.note);
    if (!data.note) root.querySelector(selector)?.setAttribute('hidden', '');
  };
  const style = root.dataset.style;
  root.dataset.day = data.day;
  set('h2', data.title);
  if (style === 'specimen') {
    set('.stamp', 'DAY ' + data.day);
    set('.tagline', '梦境切片' + (data.period ? ' / ' + data.period : ''));
    note('.quote');
    set('.annotation>div:first-child b', data.clock);
    set('.annotation>div:last-child b', data.weather);
    set('.foot>span:first-child', '采集地点 · ' + data.location);
    set('.foot>span:last-child', data.date);
  } else if (style === 'cinema') {
    set('.day', 'DAY ' + data.day);
    set('.scene-word', data.clock + (data.period ? ' / ' + data.period : ''));
    note('.screen-text p');
    const cells = root.querySelectorAll('.ticket-main>div');
    for (const cell of cells) while (cell.childNodes.length > 1) cell.removeChild(cell.lastChild);
    cells[0]?.append(document.createTextNode(data.location));
    cells[1]?.append(document.createTextNode(data.date + ' · ' + data.weather));
  } else if (style === 'observatory') {
    set('.dial strong', data.day);
    set('.dial span', data.period || data.weather);
    note('.obs-title p');
    const values = [data.time, data.location, data.weather];
    root.querySelectorAll('.coordinates>div').forEach((cell, index) => {
      while (cell.childNodes.length > 1) cell.removeChild(cell.lastChild);
      cell.append(document.createTextNode(values[index]));
    });
  } else if (style === 'book') {
    set('.margin', '美梦巡游');
    set('.top>span:first-child', 'DAY ' + data.day + ' · ' + data.time);
    set('.top>span:last-child', data.weather);
    set('.place', data.location);
    note('.epigraph');
  }
  const details = root.querySelector('details');
  const summary = details?.querySelector('summary');
  const list = details?.querySelector('.cast-list, .cast');
  const names = casts.map(entry => entry.name).filter(Boolean).join(' · ');
  if (!casts.length) {
    if (details) details.hidden = true;
  } else {
    const namesNode = summary?.querySelector('.dim');
    if (namesNode) namesNode.textContent = names;
    else if (summary) summary.textContent = '人物与关系 · ' + names;
    if (list) {
      list.replaceChildren();
      for (const entry of casts) {
        const row = document.createElement('div');
        const title = document.createElement('b');
        title.textContent = entry.name + (entry.identity ? ' · ' + entry.identity : '');
        row.append(title);
        for (const value of [entry.affinity, entry.bond]) {
          if (!value) continue;
          const line = document.createElement('p');
          line.textContent = value.replace(/^\[|\]$/g, '');
          row.append(line);
        }
        list.append(row);
      }
    }
  }
  const pause = root.querySelector('[data-action="pause"]');
  pause?.addEventListener('click', () => {
    const card = root.querySelector('.cinema');
    const paused = card.classList.toggle('paused');
    pause.setAttribute('aria-pressed', String(paused));
    pause.setAttribute('aria-label', paused ? '继续装饰动画' : '暂停装饰动画');
    pause.replaceChildren();
    const icon = document.createElement('span');
    icon.textContent = paused ? '▷' : 'Ⅱ';
    pause.append(icon, document.createTextNode(paused ? '放映' : '静帧'));
    const status = card.querySelector('.mast>span');
    status.replaceChildren();
    const lamp = document.createElement('i');
    lamp.className = 'lamp';
    status.append(lamp, document.createTextNode('美梦巡游 · ' + (paused ? '静帧' : '正在放映')));
  });
  const light = root.querySelector('[data-action="light"]');
  const themeKey = 'wx_header_observatory_theme';
  const applyLight = dawn => {
    root.querySelector('.observatory')?.classList.toggle('dawn', dawn);
    light?.setAttribute('aria-pressed', String(dawn));
    if (light) light.textContent = dawn ? '月夜' : '晨光';
  };
  if (light) {
    try { applyLight(localStorage.getItem(themeKey) === 'dawn'); } catch (_) {}
    light.addEventListener('click', () => {
      const dawn = !root.querySelector('.observatory').classList.contains('dawn');
      applyLight(dawn);
      try { localStorage.setItem(themeKey, dawn ? 'dawn' : 'night'); } catch (_) {}
    });
  }
  template.remove();
})();
</script></body></html>
