    <script>
    (function(){
        if(localStorage.getItem('choices-theme')==='dark'){
            var ws=document.querySelectorAll('.choices-wrapper');
            for(var i=0;i<ws.length;i++) ws[i].classList.add('dark-mode');
        }
        setTimeout(function(){
            var containers=document.querySelectorAll('.choices-wrapper .ch-options');
            var ct=containers[containers.length-1];
            if(!ct||ct.dataset.formatted) return;
            var html=ct.innerHTML.replace(/<\/?p>/g,'\n');
            var lines=html.split(/<br\s*\/?>|\n/);
            var choiceTexts=[];
            var fmt='';
            for(var k=0;k<lines.length;k++){
                var line=lines[k].replace(/<[^>]*>/g,'').trim();
                if(line){
                    choiceTexts.push(line);
                    fmt+='<div class="ch-option" data-idx="'+choiceTexts.length+'">'+line+'</div>';
                }
            }
            if(fmt) ct.innerHTML=fmt;
            ct.dataset.formatted='true';
            ct._choiceTexts=choiceTexts;
            var card=ct.closest('.ch-inner-card');
            var confirmRow=card.querySelector('.ch-confirm-row');
            var confirmBtn=card.querySelector('.ch-confirm-btn');
            var resetBtn=card.querySelector('.ch-reset-btn');
            var opts=ct.querySelectorAll('.ch-option');
            for(var m=0;m<opts.length;m++){
                opts[m].addEventListener('click',function(){
                    if(this.style.pointerEvents==='none') return;
                    this.classList.toggle('selected');
                    var any=ct.querySelector('.ch-option.selected');
                    if(any) confirmRow.classList.add('visible');
                    else confirmRow.classList.remove('visible');
                });
            }
            confirmBtn.addEventListener('click',function(){
                var sel=ct.querySelectorAll('.ch-option.selected');
                var texts=[];
                for(var s=0;s<sel.length;s++){
                    var idx=parseInt(sel[s].dataset.idx)-1;
                    if(ct._choiceTexts[idx]) texts.push(ct._choiceTexts[idx]);
                }
                if(!texts.length) return;
                var doc=window.parent?window.parent.document:document;
                var ta=doc.getElementById('send_textarea');
                if(ta){
                    ta.value+=(ta.value?'\n':'')+texts.join('\n');
                    ta.dispatchEvent(new Event('input',{bubbles:true}));
                    ta.focus();
                }
                var allOpts=ct.querySelectorAll('.ch-option');
                for(var s=0;s<allOpts.length;s++){
                    allOpts[s].style.opacity=allOpts[s].classList.contains('selected')?'0.5':'0.35';
                    allOpts[s].style.pointerEvents='none';
                }
                confirmBtn.innerHTML='\u2713 已填入';
                confirmBtn.style.pointerEvents='none';
                confirmBtn.style.opacity='0.7';
                resetBtn.classList.add('visible');
            });
            resetBtn.addEventListener('click',function(){
                var allOpts=ct.querySelectorAll('.ch-option');
                for(var s=0;s<allOpts.length;s++){
                    allOpts[s].classList.remove('selected');
                    allOpts[s].style.opacity='';
                    allOpts[s].style.pointerEvents='';
                }
                confirmBtn.innerHTML='确认你的抉择';
                confirmBtn.style.pointerEvents='';
                confirmBtn.style.opacity='';
                confirmRow.classList.remove('visible');
                resetBtn.classList.remove('visible');
                var doc=window.parent?window.parent.document:document;
                var ta=doc.getElementById('send_textarea');
                if(ta){ ta.value=''; ta.dispatchEvent(new Event('input',{bubbles:true})); }
            });
        },50);
    })();
    </script>
</div>
