            min-width: 260px;
            max-width: 260px;
            flex-shrink: 0;
            position: relative;
            font-family: 'VT323', 'Courier New', monospace;
            cursor: pointer;
            transition: all .6s cubic-bezier(.25,1,.5,1);
            border-radius: 15px;
            transform-style: preserve-3d;
            /* 核心：隔离内部布局，防止文字撑宽外泄 */
            contain: layout style;
            overflow: hidden;
        }

        .phn.cd .cover-face { display: block; }
        .phn:not(.cd) .cover-face { display: none; }
        .phn.cd .interior-face { display: none; }
