            display: flex;
            flex-direction: column;
            animation: oh .4s ease-out;
        }
        @keyframes oh { from { opacity: 0; transform: scaleY(.93); } to { opacity: 1; transform: scaleY(1); } }

        /* 封面 */
        .cover-face {
            height: 320px;
            border-radius: 15px;
            background: linear-gradient(170deg, #8C5E5E 0%, #6b4646 40%, #444 80%, #2f2f2f 100%);
            padding: 14px 12px;
            position: relative;
            overflow: hidden;
            border: 2px solid #2a2a2a;
            box-shadow: 0 10px 30px rgba(0,0,0,.5);
            box-sizing: border-box;
            width: 100%;
        }
        .te { display: flex; justify-content: space-between; padding: 2px 2px 0; z-index: 2; position: relative; }
        .br { font-size: 6px; color: rgba(255,255,255,.2); letter-spacing: 2px; }
        .nc { font-size: 9px; color: rgba(255,255,255,.25); }
        .os {
            background: rgba(10,15,39,.7);
            border: 2px solid #4a4a5a;
            border-radius: 7px;
            padding: 6px;
            margin: 0 2px 4px;
            min-height: 70px;
            text-align: center;
            position: relative;
            z-index: 2;
            box-sizing: border-box;
        }
        .ot { display: flex; justify-content: space-between; align-items: center; margin-bottom: 4px; }
        .osig { display: flex; align-items: flex-end; gap: 2px; }
        .sb { width: 3px; background: rgba(100,200,100,.6); border-radius: 1px; transition: height .5s; }
        .ob2 {
            width: 24px; height: 10px; border: 1.5px solid rgba(255,255,255,.4);
            border-radius: 2px; padding: 1.5px; position: relative;
            display: flex; align-items: center; box-sizing: border-box;
        }
        .ob2::after {
            content: ''; position: absolute; right: -4px; top: 2px;
            width: 3px; height: 5px; background: rgba(255,255,255,.3); border-radius: 0 1px 1px 0;
        }
        .obf2 { height: 100%; border-radius: 1px; transition: all .5s; }
        .on { font-size: .9em; color: #d4a84b; font-family: 'Cinzel Decorative', 'VT323', serif; letter-spacing: 2px; text-shadow: 0 0 10px rgba(212,168,75,.25); }
        .ou { font-size: .5em; color: rgba(255,255,255,.35); letter-spacing: 3px; margin-top: 2px; }
        .oh { font-size: .85em; margin-top: 1px; transition: opacity .5s; }
        .cu2 { position: absolute; top: 20px; left: 50%; transform: translateX(-50%); z-index: 3; display: flex; align-items: center; gap: 3px; }
        .cl { width: 8px; height: 8px; border-radius: 50%; background: radial-gradient(circle at 35% 35%, #3366ff, #000); border: 1.5px solid #555; box-shadow: 0 0 6px rgba(50,100,255,.3); }
        .cfl { width: 4px; height: 4px; border-radius: 50%; background: #ffffe0; opacity: .6; }
        .sf { position: relative; min-height: 130px; height: 130px; margin: 4px 0; z-index: 2; }
        .st { position: absolute; pointer-events: none; filter: drop-shadow(1px 1px 2px rgba(0,0,0,.4)); }
        .oh2 { position: absolute; bottom: 4px; left: 50%; transform: translateX(-50%); font-size: 6px; color: rgba(255,255,255,.15); letter-spacing: 3px; z-index: 2; }

        /* 内页 */
        .interior-face {
            width: 100%;
            border-radius: 15px;
            background: #1a1a1a;
            padding: 10px;
            border: 2px solid #2a2a2a;
            box-shadow: 0 10px 30px rgba(0,0,0,.5);
            box-sizing: border-box;
            overflow: hidden;
        }
        .top-half, .bottom-half {
            height: 300px;
            display: flex;
            flex-direction: column;
            box-sizing: border-box;
        }
        .screen-bezel {
            background: #111;
            padding: 6px;
            border-radius: 8px 8px 0 0;
            border: 1px solid #333;
            flex: 1;
            display: flex;
            flex-direction: column;
            position: relative;
            box-sizing: border-box;
            overflow: hidden;
        }
        .ps {
            background: #f4f4e8;
            color: #1a1a1a;
            font-family: 'VT323', monospace;
            padding: 5px;
            border: 2px inset #d0d0c0;
            border-radius: 3px;
            flex: 1;
            display: flex;
            flex-direction: column;
            background-image: linear-gradient(rgba(0,0,0,.03) 50%, transparent 50%);
            background-size: 100% 3px;
            cursor: default;
            box-sizing: border-box;
            overflow: hidden;
        }
        .ms { border-radius: 4px; z-index: 5; }
        .psc {
            flex: 1;
            overflow-y: auto;
            overflow-x: hidden;
            box-sizing: border-box;
            word-break: break-word;
            overflow-wrap: break-word;
        }
        .phd { display: flex; justify-content: space-between; font-size: 12px; border-bottom: 2px solid #003366; margin-bottom: 3px; padding-bottom: 2px; flex-shrink: 0; }
        .hn { color: #003366; font-weight: bold; }
        .hf { color: #666; font-size: 11px; }
        .va { display: flex; gap: 5px; align-items: flex-start; margin-bottom: 4px; flex-shrink: 0; }
        .pb { font-size: 36px; width: 50px; height: 50px; display: flex; align-items: center; justify-content: center; border: 2px solid #1a1a1a; background: #fff; flex-shrink: 0; }
        .pi { flex: 1; font-size: 14px; display: flex; flex-direction: column; gap: 1px; min-width: 0; }
        .pr { border-bottom: 1px dotted #ccc; line-height: 1.2; }
        .pr .lb { color: #003366; font-weight: bold; margin-right: 4px; }
        .mb { flex-shrink: 0; border: 1px solid #ccc; background: rgba(255,255,255,.5); margin-bottom: 2px; }
        .mt { background: #1a1a1a; color: #fff; padding: 0 4px; font-size: 10px; flex-shrink: 0; }
        .mc { padding: 1px 4px; font-size: 12px; color: #333; }
        .pf2 { font-size: 10px; border-top: 1px solid #ccc; padding-top: 2px; text-align: right; flex-shrink: 0; }
        .sw-btn { display: inline-block; padding: 1px 10px; background: #003366; color: #f4f4e8; border-radius: 2px; cursor: pointer; letter-spacing: 1px; user-select: none; transition: background .2s; }
        .sw-btn:hover { background: #004488; }
        .sw-btn:active { background: #002244; }
        .btag { position: absolute; bottom: 4px; left: 0; right: 0; text-align: center; font-size: 11px; color: #666; letter-spacing: 2px; pointer-events: none; }

        /* 转轴 */
        .hj {
            height: 28px;
            flex-shrink: 0;
            background: linear-gradient(90deg, #1a1a1a 0%, #333 30%, #444 50%, #333 70%, #1a1a1a 100%);
            margin: 2px -10px;
            position: relative;
            border-top: 1px solid #000;
            border-bottom: 1px solid #000;
            box-sizing: border-box;
        }
        .hj-inner { position: absolute; left: 20%; right: 20%; top: 50%; transform: translateY(-50%); height: 6px; background: linear-gradient(90deg, transparent 0%, rgba(255,255,255,.08) 20%, rgba(255,255,255,.12) 50%, rgba(255,255,255,.08) 80%, transparent 100%); border-radius: 3px; }
        .hj::after, .hj::before { content: ""; position: absolute; left: 5px; right: 5px; }
        .hj::after { top: 4px; height: 1px; background: rgba(255,255,255,.05); border-radius: 1px; }
        .hj::before { bottom: 4px; height: 2px; background: #0a0a0a; border-radius: 1px; }

        /* 下半屏 */
        .keypad-frame {
            background: #111;
            padding: 6px;
            border-radius: 0 0 8px 8px;
            border: 1px solid #333;
            flex: 1;
            display: flex;
            flex-direction: column;
            box-sizing: border-box;
            overflow: hidden;
        }
        .bottom-half { padding-top: 0; }
        .sttl { font-size: 10px; background: #003366; color: #fff; padding: 1px 4px; margin-bottom: 3px; flex-shrink: 0; }

        /* ========= 思维监测：Grid锁死宽度 + 强制断行 ========= */
        .tgs {
            display: grid;
            grid-template-columns: 1fr;
            gap: 3px;
            width: 100%;
            margin: 3px 0;
        }
        .tb {
            width: 100%;
            min-height: 22px;
            border: 1px dashed #888;
            font-size: 12px;
            background: rgba(255,255,255,.5);
            opacity: 0;
            box-sizing: border-box;
            padding: 2px 4px;
            word-break: break-all;
            overflow-wrap: anywhere;
            line-height: 1.3;
        }
        .tb.d { color: #8b0000; }
        .tb.a { color: #003366; }
        .tb.s { color: #333; }
        .tb .vi { margin-right: 4px; font-weight: bold; }
        .tb .tt { display: inline; }
        .tc { display: inline; font-weight: bold; animation: bk .7s step-end infinite; }
        @keyframes bk { 50% { opacity: 0; } }
        @keyframes bi { 0% { transform: translateY(8px); opacity: 0; } 60% { transform: translateY(-2px); } 100% { transform: translateY(0); opacity: 1; } }

        .py { margin-top: 4px; border: 1.5px solid #8b0000; border-radius: 2px; padding: 2px 3px; background: rgba(139,0,0,.04); flex-shrink: 0; }
        .pyt { font-size: 9px; color: #8b0000; font-weight: bold; margin-bottom: 1px; }
        .pyc { font-size: 11px; color: #555; line-height: 1.3; }
        .ld { color: #8b0000; font-size: 11px; }
        .bd { color: #333; font-size: 11px; }
        .pl { margin-top: 2px; font-size: 12px; color: #333; line-height: 1.2; }

        /* 挂链 */
        .charm { position: absolute; top: 8px; right: -6px; z-index: 25; pointer-events: none; animation: sw 4s infinite ease-in-out; }
        @keyframes sw { 0%, 100% { transform: rotate(-3deg); } 50% { transform: rotate(3deg); } }
        .cc { width: 1.5px; height: 25px; background: #bbb; border-left: 1px dashed #888; margin: 0 auto; }
        .ct2 { width: 24px; height: 18px; background: #fff; border: 1px solid #444; border-radius: 2px; overflow: hidden; box-shadow: 0 2px 4px rgba(0,0,0,.3); }
        .cf2 { width: 200%; height: 100%; background-image: conic-gradient(#fff 90deg, #000 90deg 180deg, #fff 180deg 270deg, #000 270deg); background-size: 5px 5px; animation: fw .6s linear infinite; }
        @keyframes fw { from { transform: translateX(0); } to { transform: translateX(-12px); } }

        ::-webkit-scrollbar { width: 2px; }
        ::-webkit-scrollbar-track { background: rgba(0,0,0,.03); }
        ::-webkit-scrollbar-thumb { background: #ccc; border-radius: 2px; }

        /* 手机端依旧固定260px */
        @media (max-width: 480px) {
            .phn {
                width: 260px;
                min-width: 260px;
                max-width: 260px;
            }
            .cover-face { height: 280px; padding: 10px 8px; }
            .top-half, .bottom-half { height: 260px; }
            .sf { min-height: 110px; height: 110px; }
            .pb { font-size: 30px; width: 42px; height: 42px; }
            .hj { height: 24px; margin: 2px -8px; }
            .charm { top: 6px; right: -4px; }
            .cc { height: 20px; }
            .ct2 { width: 20px; height: 15px; }
        }
/* ── 修复手机端流式文字撑宽 ── */
.phn{max-width:100%;min-width:0}
.tgs{min-width:0}
.tb{min-width:0;max-width:100%;white-space:normal;overflow-wrap:anywhere;word-break:break-all;box-sizing:border-box}
.tb .tt{white-space:normal;overflow-wrap:anywhere;word-break:break-all;display:inline}
.ps,.psc,.screen-bezel,.keypad-frame,.top-half,.bottom-half{min-width:0;max-width:100%;box-sizing:border-box}
    </style>
</head>
<body>
    <div class="wrapper"></div>

    <script>
    (function() {
        // ========== 您的原始数据占位 ==========
        var raw = `$1`.replace(/<br\s*\/?>/gi, '\n').replace(/<\/p>/gi, '\n');

        function ext(t, k, nx) {
            var p = nx.length ? '(?=' + nx.join('|') + '|$)' : '(?=$)';
            var re = new RegExp(k + '[：:]([\\s\\S]*?)' + p, 'i');
            var m = t.match(re);
            return m ? m[1].trim() : '';
        }

        var bs = raw.match(/<char\d+>([\s\S]*?)<\/char\d+>/gi) || [];
        if (!bs.length && raw.includes('角色名称')) bs = [raw];
        var cs = [];
        bs.forEach(function(b) {
            var t = b.replace(/<[^>]+>/g, '').trim();
            if (!t) return;
            var o = {};
            o.name = ext(t, '角色名称', ['好感指数', '隐秘心声', '私密锚定', '待办事项', '羁绊暗流', '未竟因果']);
            o.fav = ext(t, '好感指数', ['隐秘心声', '私密锚定', '待办事项', '羁绊暗流', '未竟因果']);
            o.mind = ext(t, '隐秘心声', ['私密锚定', '待办事项', '羁绊暗流', '未竟因果']);
            o.priv = ext(t, '私密锚定', ['待办事项', '羁绊暗流', '未竟因果']);
            o.todo = ext(t, '待办事项', ['羁绊暗流', '未竟因果']);
            o.bond = ext(t, '羁绊暗流', ['未竟因果']);
            o.karma = ext(t, '未竟因果', []);
            o.favNum = 0; o.favStage = o.fav; o.favReason = ''; o.favDelta = '';
            if (o.fav) {
                var nm = o.fav.match(/-?\d+/); if (nm) o.favNum = parseInt(nm[0]);
                var dm = o.fav.match(/\(([+-]\d+[^)]*)\)/);
                if (dm) {
                    o.favStage = o.fav.substring(0, o.fav.indexOf(dm[0])).trim();
                    var dn = dm[1].match(/[+-]\d+/); if (dn) o.favDelta = dn[0];
                }
                var rm = o.fav.match(/原因[：:](.*)/i); if (rm) o.favReason = rm[1].trim();
            }
            o.id = ''; o.sup = ''; o.ego = '';
            if (o.mind) {
                var a = o.mind.match(/【(?:本我|三尸)】[：:]?\s*([\s\S]*?)(?=【(?:超我|元神)】|$)/);
                if (a) o.id = a[1].trim();
                var b = o.mind.match(/【(?:超我|元神)】[：:]?\s*([\s\S]*?)(?=【(?:自我|神识)】|$)/);
                if (b) o.sup = b[1].trim();
                var d = o.mind.match(/【(?:自我|神识)】[：:]?\s*([\s\S]*?)$/);
                if (d) o.ego = d[1].trim();
            }
            o.und = ''; o.phy = '';
            if (o.priv) {
                var p = o.priv.replace(/｜/g, '|');
                var u = p.match(/内衣裤[：:](.*?)(?=\||$)/); if (u) o.und = u[1].trim();
                var h = p.match(/生理[：:](.*?)$/); if (h) o.phy = h[1].trim();
            }
            o.todos = [];
            if (o.todo) o.todo.split(/\n/).forEach(function(l) {
                var m = l.match(/-\s*\[([ ✔✓✗✘])]\s*(.*)/);
                if (m) o.todos.push({ d: m[1] !== ' ', t: m[2].replace(/~~/g, '').trim() });
            });
            if (!o.todos.length) o.todos = [{ d: false, t: '暂无待办' }];
            cs.push(o);
        });

        if (!cs.length) {
            document.querySelector('.wrapper').innerHTML = '<div style="padding:16px;text-align:center;opacity:.6;">无状态</div>';
            return;
        }

        var ci = 0;

        function typeEffect(el) {
            el.querySelectorAll('.tb[data-t]').forEach(function(b, i) {
                var text = b.getAttribute('data-t') || '',
                    ts = b.querySelector('.tt'),
                    tc = b.querySelector('.tc');
                if (!ts) return;
                ts.textContent = '';
                if (tc) tc.style.display = 'inline';
                b.style.animation = 'none';
                void b.offsetHeight;
                b.style.animation = 'bi .4s ease';
                b.style.opacity = '1';
                var pos = 0;
                function write() {
                    if (pos < text.length) {
                        ts.textContent += text[pos];
                        pos++;
                        setTimeout(write, 25 + Math.random() * 25);
                    } else if (tc) tc.style.display = 'none';
                }
                setTimeout(write, i * 700);
            });
        }

        function render(idx) {
            var c = cs[idx], th = '';
            c.todos.forEach(function(t) {
                th += '<div class="pl"><span style="color:#8b0000">' + (t.d ? '✔' : '□') + '</span> ' + (t.d ? '<s>' + t.t + '</s>' : t.t) + '</div>';
            });

            var id = 'f_' + Math.random().toString(36).substr(2, 9),
                fav = c.favNum;
            var sc = 0;
            if (fav >= 0) sc = 1; if (fav >= 20) sc = 3; if (fav >= 40) sc = 6; if (fav >= 60) sc = 9; if (fav >= 80) sc = 12; if (fav >= 90) sc = 14;
            var sig = Math.min(4, Math.floor(fav / 25) + 1),
                bat = Math.min(100, Math.max(5, Math.floor(fav * 0.9 + 10)));
            var batColor = bat > 40 ? '#4a4' : '#c44';
            var em = '😑';
            if (fav < -30) em = '🗡️'; else if (fav < 0) em = '😠'; else if (fav < 20) em = '😏'; else if (fav < 40) em = '😑'; else if (fav < 60) em = '😲'; else if (fav < 80) em = '😊'; else em = '🥰';

            var ph = '';
            if (c.und) ph += '<div class="ld">' + c.und + '</div>';
            if (c.phy) ph += '<div class="bd">' + c.phy + '</div>';
            if (!ph) ph = '<div class="bd" style="opacity:.5;">—</div>';
            if (c.karma) ph += '<div style="color:#555;font-size:10px;margin-top:1px;">因果:' + c.karma + '</div>';

            // 思维监测（保留原有结构）
            var tgh = '<div class="tb d"><span class="vi">👿</span><span class="tt"></span><span class="tc">▍</span></div>' +
                      '<div class="tb a"><span class="vi">👼</span><span class="tt"></span><span class="tc">▍</span></div>' +
                      '<div class="tb s"><span class="vi">⚖️</span><span class="tt"></span><span class="tc">▍</span></div>';

            var stickerData = [
                {emo:'🏎️',x:10,y:8,s:1.1},{emo:'🔥',x:75,y:2,s:.8},{emo:'🚗',x:5,y:48,s:.9},
                {emo:'🚓',x:80,y:42,s:.85},{emo:'⛽',x:15,y:82,s:.7},{emo:'🚧',x:70,y:85,s:.75},
                {emo:'🏆',x:55,y:6,s:1.3},{emo:'🚦',x:88,y:65,s:.8},{emo:'⚠️',x:35,y:15,s:.6},
                {emo:'💝',x:28,y:52,s:1},{emo:'💌',x:60,y:52,s:.9},{emo:'🏁',x:42,y:72,s:1.2},
                {emo:'🌟',x:50,y:22,s:1.1},{emo:'❤️‍🔥',x:68,y:18,s:1}
            ];
            var sh = '';
            for (var si = 0; si < Math.min(sc, stickerData.length); si++) {
                var d = stickerData[si];
                sh += '<span class="st" style="left:' + d.x + '%;top:' + d.y + '%;font-size:' + d.s + 'em">' + d.emo + '</span>';
            }

            // 生成完整HTML
            var html = `
            <div class="phn" id="el_${id}">
                <div class="charm"><div class="cc"></div><div class="ct2"><div class="cf2"></div></div></div>
                <div class="cover-face">
                    <div class="te"><span class="br">NOKIA</span><span class="nc">✦</span></div>
                    <div class="os">
                        <div class="ot">
                            <span class="osig">
                                <span class="sb" style="height:${sig>=1?'6px':'2px'}"></span>
                                <span class="sb" style="height:${sig>=2?'10px':'2px'}"></span>
                                <span class="sb" style="height:${sig>=3?'14px':'2px'}"></span>
                                <span class="sb" style="height:${sig>=4?'18px':'2px'}"></span>
                            </span>
                            <div class="ob2"><span class="obf2" style="width:${bat}%;background:${batColor}"></span></div>
                        </div>
                        <div class="on">${c.name||'???'}</div>
                        ${fav>=90?'<div class="ou">✦ {{user}} ✦</div>':''}
                        <div class="oh" style="opacity:${fav>50?Math.min(1,(fav-50)/50):0}">❤️</div>
                    </div>
                    <div class="cu2"><div class="cl"></div><div class="cfl"></div></div>
                    <div class="sf">${sh}</div>
                    <div class="oh2">▽ 翻开</div>
                </div>
                <div class="interior-face">
                    <div class="top-half">
                        <div class="screen-bezel">
                            <div class="ps ms">
                                <div class="phd"><span class="hn">${c.name||'???'}</span><span class="hf">${c.favStage||'-'} ${c.favNum}/100${c.favDelta?' ('+c.favDelta+')':''}</span></div>
                                <div class="psc">
                                    <div class="va"><span class="pb">${em}</span><div class="pi">
                                        <div class="pr"><span class="lb">好感:</span> ${c.favNum}${c.favDelta?' <span style="color:'+(parseInt(c.favDelta)>0?'#2a7':'#c44')+'">('+c.favDelta+')</span>':''}</div>
                                        ${c.favReason?'<div class="pr"><span class="lb">原因:</span> '+c.favReason+'</div>':''}
                                    </div></div>
                                    <div class="mb"><div class="mt">/// 待办 ///</div><div class="mc">${th}</div></div>
                                </div>
                                <div class="pf2">${cs.length>1?'<span class="sw-btn" id="sw_'+id+'">&lt; '+(ci+1)+'/'+cs.length+' &gt;</span>':'>> 系统运行'}</div>
                            </div>
                            <div class="btag">DoCoMo</div>
                        </div>
                    </div>
                    <div class="hj"><div class="hj-inner"></div></div>
                    <div class="bottom-half">
                        <div class="keypad-frame">
                            <div class="ps">
                                <div class="sttl">/// 思维监测 ///</div>
                                <div class="psc">
                                    <div class="tgs">${tgh}</div>
                                    <div class="py"><div class="pyt">[生理]</div><div class="pyc">${ph}</div></div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>`;

            // 插入到 wrapper 中（安全方式）
            var wrapper = document.querySelector('.wrapper');
            wrapper.innerHTML = '';
            var container = document.createElement('div');
            container.id = id;
            container.innerHTML = html;
            wrapper.appendChild(container);
            // 用 DOM 属性传递原文，避免 HTML 属性解析截断引号或解码实体。
            var mindTexts = [c.id || '(无声)', c.sup || '(无声)', c.ego || '(权衡中)'];
            container.querySelectorAll('.tgs .tb').forEach(function(box, index) {
                box.dataset.t = mindTexts[index];
            });

            var el = document.getElementById('el_' + id);
            if (!el) return;
            el.addEventListener('click', function(e) {
                if (e.target.classList.contains('sw-btn')) return;
                this.classList.toggle('cd');
                if (!this.classList.contains('cd')) setTimeout(function() { typeEffect(el); }, 400);
            });

            if (cs.length > 1) {
                var sw = document.getElementById('sw_' + id);
                if (sw) sw.addEventListener('click', function(e) {
                    e.stopPropagation();
                    ci = (ci + 1) % cs.length;
                    render(ci);
                });
            }

            setTimeout(function() { typeEffect(el); }, 400);
        }

        render(0);
    })();
    </script>
