    var re=new RegExp(k+'[：:]([\\s\\S]*?)'+p,'i');
    var m=t.match(re);return m?m[1].trim():'';
  }

  var chars=[];
  blocks.forEach(function(b){
    var t=b.replace(/<[^>]+>/g,'').trim(); if(!t) return;
