    c.mind=pick(t,'隐秘心声',['私密锚定','待办事项','羁绊暗流','未竟因果']);
    c.priv=pick(t,'私密锚定',['待办事项','羁绊暗流','未竟因果']);
    c.todo=pick(t,'待办事项',['羁绊暗流','未竟因果']);
