    c.id='';c.sup='';c.ego='';
    if(c.mind){var a=c.mind.match(/【(?:本我|三尸)】[：:]?\s*([\s\S]*?)(?=【(?:超我|元神)】|$)/);if(a)c.id=a[1].trim();var b=c.mind.match(/【(?:超我|元神)】[：:]?\s*([\s\S]*?)(?=【(?:自我|神识)】|$)/);if(b)c.sup=b[1].trim();var d=c.mind.match(/【(?:自我|神识)】[：:]?\s*([\s\S]*?)$/);if(d)c.ego=d[1].trim();}
    c.und='';c.phy='';if(c.priv){var p=c.priv.replace(/｜/g,'|');var u=p.match(/内衣裤[：:](.*?)(?=\||$)/);if(u)c.und=u[1].trim();var h=p.match(/生理[：:](.*?)$/);if(h)c.phy=h[1].trim();}
    c.todos=[];if(c.todo)c.todo.split(/\n/).forEach(function(l){var m=l.match(/-\s*\[([ ✔✓✗✘])]\s*(.*)/);if(m)c.todos.push({done:m[1]!==' ',text:m[2].replace(/~~/g,'').trim()});});
    c.bonds=c.bond?c.bond.split(/\n/).map(function(l){return l.trim()}).filter(Boolean):[];
