    if(d.fav){
      var lit=Math.round((Math.min(100,Math.abs(d.favNum))/100)*10);if(lit>10)lit=10;if(lit<0)lit=0;
      h+='<div class="fh"><span class="fs">'+d.favStage+'</span><span style="font-size:.9em;color:#666;">'+d.favNum+'/100'+(d.favDelta?' ('+d.favDelta+')':'')+'</span></div>';
