          '<span class="me">🪞</span><span class="ml">'+df.l+'</span></div>';
      });
      h+='</div><div class="ct"><div class="ctl" id="ctl_'+idx+'"></div><div class="ctb" id="ctb_'+idx+'"></div></div></div>';
    } else if(d.mind){
      h+='<div class="st">🪞 明镜照心</div><div style="text-align:center;padding:12px;color:var(--ink-l);font-size:.95em;line-height:1.8;">'+d.mind+'</div>';
    }

