    if(d.karma){h+='<div class="st">⚖️ 未竞因果</div><div class="bt2">'+d.karma+'</div>';}
    return h||'<div style="padding:16px;text-align:center;opacity:.6;">暂无状态</div>';
  }

  if(!chars.length){box.innerHTML=renderChar({});return;}
  title.textContent=chars[0].name||'无名';

  if(chars.length===1){
