      });
      if(!paused){
        var best=-1,bestDist=999;
        mirrors.forEach(function(m,i){
          var a=((initAngles[i]+angle)%360+360)%360;
          var dist=Math.min(Math.abs(a-270),Math.abs(a+90));
          if(dist<bestDist){bestDist=dist;best=i;}
