        if(best>=0){
          mirrors.forEach(function(m){m.classList.remove('active');});
          mirrors[best].classList.add('active');
          if(ctl&&ctb){
            ctl.textContent=(mirrors[best].querySelector('.ml')||{}).textContent||'';
            ctb.textContent=mirrors[best].getAttribute('data-t')||'';
          }
        }
      }
    }
    mirrors.forEach(function(m,mi){
      m.addEventListener('click',function(e){
        e.stopPropagation();
        if(paused&&pausedIdx===mi){
          paused=false;pausedIdx=-1;
          mirrors.forEach(function(m2){m2.classList.remove('active');});
          angle=(angle+0.5)%360;updatePositions();
        } else {
          paused=true;pausedIdx=mi;
          mirrors.forEach(function(m2){m2.classList.remove('active');});
          m.classList.add('active');
          if(ctl&&ctb){
            ctl.textContent=(m.querySelector('.ml')||{}).textContent||'';
            ctb.textContent=m.getAttribute('data-t')||'';
          }
        }
      });
    });
    setTimeout(function(){updatePositions();setInterval(function(){if(!paused){angle=(angle+0.5)%360;updatePositions();}},50);},200);
  });

  // ===== 宣纸撕开 =====
  document.querySelectorAll('.paper-w').forEach(function(w){
    w.addEventListener('click',function(){
      var l=this.querySelector('.paper-l'),r=this.querySelector('.paper-r');
      if(l&&r){l.classList.toggle('fly');r.classList.toggle('fly');}
    });
  });

} catch(e){
  document.getElementById('bookContent').innerHTML='<div style="padding:16px;color:var(--red);">[书页微损]</div>';
}
})();
</script>
