.ap.cd .cf{display:flex}
.env{width:100%;background:linear-gradient(170deg,#0f1438 0%,#1a1e42 50%,#0a0e27 100%);border-radius:10px;border:2px solid #4a3f28;position:relative;min-height:200px;display:flex;align-items:center;justify-content:center;box-shadow:2px 4px 16px rgba(0,0,0,.25)}
.env::before{content:'';position:absolute;inset:0;background:radial-gradient(ellipse at 30% 40%,rgba(74,122,204,.12) 0%,transparent 60%),radial-gradient(ellipse at 70% 60%,rgba(212,168,75,.06) 0%,transparent 50%);border-radius:10px;pointer-events:none}
.env-stars{position:absolute;inset:0;pointer-events:none;border-radius:10px;overflow:hidden}
.env-stars span{position:absolute;width:2px;height:2px;background:#fff;border-radius:50%;animation:tw var(--d,3s) ease-in-out infinite alternate}
.env-flap{position:absolute;top:-2px;left:-2px;right:-2px;height:50%;background:linear-gradient(170deg,#1a1e42 0%,#0f1438 100%);border:2px solid #4a3f28;border-radius:10px 10px 0 0;transform-origin:top;transition:all .6s;clip-path:polygon(0 0,100% 0,100% 100%,50% 65%,0 100%);z-index:2}
.env-flap::before{content:'';position:absolute;inset:0;background:radial-gradient(ellipse at 30% 30%,rgba(74,122,204,.1) 0%,transparent 60%);border-radius:10px 10px 0 0}
.ap.cd .env-flap{transform:rotateX(0deg)}
.env-body{text-align:center;z-index:1;padding:20px}
.env-seal{width:44px;height:44px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#c04040 0%,#8b1a1a 60%);display:flex;align-items:center;justify-content:center;margin:0 auto 8px;box-shadow:0 2px 8px rgba(139,26,26,.4)}
.env-seal-inner{width:28px;height:28px;border-radius:50%;border:1.5px solid rgba(255,200,100,.5);display:flex;align-items:center;justify-content:center;font-size:14px;color:rgba(255,200,100,.7);font-family:'Cinzel Decorative',serif}
.env-to{font-size:.65em;color:rgba(212,168,75,.5);letter-spacing:4px;font-family:'MedievalSharp',serif;margin-top:4px}
.env-to-name{font-size:.9em;color:#d4a84b;font-family:'Cinzel Decorative',serif;letter-spacing:2px;margin-top:2px;text-shadow:0 0 8px rgba(212,168,75,.2)}

/* 内页（展开时显示） */
.if{display:flex;flex-direction:column;gap:0}
.ap.cd .if{display:none}

/* 星穹头饰 */
.sky-header{background:linear-gradient(170deg,#0f1438 0%,#1a1e42 50%,#0a0e27 100%);border-radius:12px 12px 0 0;padding:18px 16px 12px;position:relative;overflow:hidden;text-align:center;border:2px solid #4a3f28;border-bottom:none}
.sky-header::before{content:'';position:absolute;inset:0;background:radial-gradient(ellipse at 30% 40%,rgba(74,122,204,.12) 0%,transparent 60%),radial-gradient(ellipse at 70% 60%,rgba(212,168,75,.06) 0%,transparent 50%)}
.sky-name{font-family:'Cinzel Decorative',serif;font-size:1.1em;color:#d4a84b;letter-spacing:4px;text-shadow:0 0 12px rgba(212,168,75,.25);position:relative;z-index:1}
.sky-sub{font-size:.5em;font-family:'MedievalSharp',serif;color:rgba(212,168,75,.4);letter-spacing:5px;margin-top:4px;position:relative;z-index:1}
.sky-stars{position:absolute;inset:0;pointer-events:none}
.sky-stars span{position:absolute;width:2px;height:2px;background:#fff;border-radius:50%;animation:tw var(--d,3s) ease-in-out infinite alternate}
@keyframes tw{0%{opacity:.2}100%{opacity:.8}}

/* 羊皮纸内容 */
.parchment{background:linear-gradient(180deg,#f5f0e6 0%,#efe8da 100%);border:2px solid #4a3f28;border-top:none;border-radius:0 0 12px 12px;padding:14px 16px}

.s-title{font-family:'Cinzel Decorative',serif;font-size:.75em;color:#3a2a1a;margin:10px 0 6px;display:flex;align-items:center;gap:6px;border-bottom:1px solid rgba(58,42,26,.1);padding-bottom:4px;letter-spacing:2px}
.s-title:first-child{margin-top:0}

/* 好感 = 星座散点连线 */
.fv-box{border-left:2px solid #d4a84b;padding-left:10px;margin-bottom:2px}
.fv-hd{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:4px}
.fv-stage{font-family:'Cinzel Decorative',serif;font-size:.8em;color:#3a2a1a}
.const-box{background:rgba(10,15,39,.04);border:1px solid rgba(212,168,75,.2);border-radius:5px;padding:8px;margin:4px 0;position:relative;height:120px}
.const-sky{position:relative;width:100%;height:100%}
.const-sky svg{position:absolute;inset:0;width:100%;height:100%;z-index:1;pointer-events:none}
.const-sky svg line{stroke:rgba(212,168,75,.15);stroke-width:1;transition:stroke .5s}
.const-sky svg line.on{stroke:rgba(212,168,75,.5)}
.const-star{position:absolute;z-index:2;font-size:1.1em;color:rgba(10,15,39,.12);transition:all .4s cubic-bezier(.34,1.56,.64,1);line-height:1;transform:translate(-50%,-50%)}
.const-star.on{color:#d4a84b;text-shadow:0 0 8px rgba(212,168,75,.5),0 0 16px rgba(212,168,75,.2);transform:translate(-50%,-50%) scale(1.25)}
.const-star.half{background:linear-gradient(90deg,#d4a84b 50%,rgba(10,15,39,.12) 50%);-webkit-background-clip:text;background-clip:text;color:transparent;text-shadow:none;transform:translate(-50%,-50%) scale(1.1)}
.const-label{font-size:.6em;color:#8a7a6a;text-align:center;margin-top:4px;font-family:'MedievalSharp',serif;letter-spacing:1px;clear:both}
.fv-reason{font-size:.75em;color:#8a7a6a;text-align:right;margin-top:3px;font-style:italic}

/* 内心低语（散乱→归位） */
.voices{padding:2px 0}
.voice-block{padding:6px 8px;border:1px dashed #c8b8a0;font-size:.8em;background:rgba(245,240,230,.8);margin-bottom:4px;line-height:1.6;border-radius:3px;position:relative;min-height:2em;cursor:pointer;transition:border-color .3s}
.voice-block:hover{border-color:#a08060}
.voice-block .vi{margin-right:4px}
.voice-block.v1{color:#5a3a7a}.voice-block.v2{color:#3a6aaa}.voice-block.v3{color:#6a4a2a}
.scatter-char{display:inline-block;transition:all .35s cubic-bezier(.34,1.56,.64,1);position:relative}
.scatter-char.fixed{transform:translate(0,0)!important;opacity:1!important}
@keyframes flick{0%,100%{opacity:1}30%{opacity:.3}70%{opacity:.8}}
.flicker{animation:flick .12s ease-in-out 4}

/* 私密 */
.priv-row{display:flex;gap:8px;flex-wrap:wrap;margin:4px 0}
.priv-tag{font-size:.75em;color:#5a4a3a;padding:2px 8px;background:rgba(212,168,75,.07);border-radius:10px;border:1px solid rgba(212,168,75,.18)}

/* 待办 */
.todo-box{border:1px solid rgba(58,42,26,.12);border-radius:3px;padding:5px 8px;margin:4px 0;background:rgba(255,255,255,.3)}
.todo-line{font-size:.78em;color:#5a4a3a;padding:1px 0;line-height:1.4}
.todo-line.done{opacity:.5}

/* 羁绊/因果 */
.bond-text{font-size:.78em;color:#5a4a3a;line-height:1.6;padding-left:8px;margin-bottom:4px;border-left:2px solid rgba(212,168,75,.25)}

/* 翻页 */
.flip-btn{text-align:center;margin-top:8px;padding-top:6px;border-top:1px dashed rgba(58,42,26,.12);font-family:'Cinzel Decorative',serif;font-size:.6em;color:#d4a84b;cursor:pointer;opacity:.6;letter-spacing:2px}
.flip-btn:hover{opacity:1}

/* 手机适配 */
@media(max-width:480px){
.ap{width:94%!important;max-width:300px!important}
.ap.cd{width:88%!important}
.parchment{padding:10px 10px}
.sky-header{padding:14px 10px 10px}
.env{min-height:160px}
.const-box{height:100px}
.const-star{font-size:.9em}
.voice-block{font-size:.75em}
}
</style>
</head>
<body>

<script>
(function(){
    var raw = `$1`.replace(/<br\s*\/?>/gi,'\n').replace(/<\/p>/gi,'\n');

    function ext(t,k,next){
        var p=next.length?'(?='+next.join('|')+'|$)':'(?=$)';
        var re=new RegExp(k+'[：:]\\s*([\\s\\S]*?)'+p,'i');
        return (m=t.match(re))?m[1].trim():'';
    }

    var blocks = raw.match(/<char\d+>([\s\S]*?)<\/char\d+>/gi) || [];
    if(!blocks.length && raw.includes('角色名称')) blocks=[raw];

    var chars=[];
    blocks.forEach(function(b){
        var t=b.replace(/<[^>]+>/g,'').trim(); if(!t) return;
        var o={};
        o.name=ext(t,'角色名称',['好感指数','隐秘心声','私密锚定','待办事项','羁绊暗流','未竟因果']);
        o.fav=ext(t,'好感指数',['隐秘心声','私密锚定','待办事项','羁绊暗流','未竟因果']);
        o.mind=ext(t,'隐秘心声',['私密锚定','待办事项','羁绊暗流','未竟因果']);
        o.priv=ext(t,'私密锚定',['待办事项','羁绊暗流','未竟因果']);
        o.todo=ext(t,'待办事项',['羁绊暗流','未竟因果']);
        o.bond=ext(t,'羁绊暗流',['未竟因果']);
        o.karma=ext(t,'未竟因果',[]);

        o.favNum=0; o.favStage=o.fav; o.favReason=''; o.favDelta='';
        if(o.fav){
            var nm=o.fav.match(/-?\d+/);
            if(nm) o.favNum=parseInt(nm[0]);
            var dm=o.fav.match(/\(([+-]\d+[^)]*)\)/);
            if(dm){o.favStage=o.fav.substring(0,o.fav.indexOf(dm[0])).trim();var dn=dm[1].match(/[+-]\d+/);if(dn)o.favDelta=dn[0];}
            var rm=o.fav.match(/原因[：:](.*)/i);
            if(rm) o.favReason=rm[1].trim();
        }

        o.id='';o.sup='';o.ego='';
        if(o.mind){
            var a=o.mind.match(/【(?:本我|三尸)】[：:]?\s*([\s\S]*?)(?=【(?:超我|元神)】|$)/);
            if(a) o.id=a[1].trim();
            var b=o.mind.match(/【(?:超我|元神)】[：:]?\s*([\s\S]*?)(?=【(?:自我|神识)】|$)/);
            if(b) o.sup=b[1].trim();
            var d=o.mind.match(/【(?:自我|神识)】[：:]?\s*([\s\S]*?)$/);
            if(d) o.ego=d[1].trim();
        }

        o.und='';o.phy='';
        if(o.priv){
            var p=o.priv.replace(/｜/g,'|');
            var u=p.match(/内衣裤[：:](.*?)(?=\||$)/);
            if(u) o.und=u[1].trim();
            var h=p.match(/生理[：:](.*?)$/);
            if(h) o.phy=h[1].trim();
        }

        o.todos=[];
        if(o.todo) o.todo.split(/\n/).forEach(function(l){
            var m=l.match(/-\s*\[([ ✔✓✗✘])]\s*(.*)/);
            if(m) o.todos.push({d:m[1]!==' ',t:m[2].replace(/~~/g,'').trim()});
        });
        if(!o.todos.length) o.todos=[{d:false,t:'暂无待办'}];
        chars.push(o);
    });

    if(!chars.length){document.write('<div style="padding:16px;text-align:center;opacity:.6;">无角色状态</div>');return;}

    var curIdx=0;

    // ===== 散乱归位 =====
    function scatterText(el){
        var vbs=el.querySelectorAll('.voice-block[data-t]');
        vbs.forEach(function(vb,i){
            var full=vb.getAttribute('data-t')||'';
            var wrap=vb.querySelector('.scatter-wrap');
            if(!wrap) return;
            var chars=full.split('');
            for(var si=chars.length-1;si>0;si--){var j=Math.floor(Math.random()*(si+1));var tmp=chars[si];chars[si]=chars[j];chars[j]=tmp;}
            var h='';
            chars.forEach(function(ch){
                var tx=Math.random()*60-30,ty=Math.random()*40-20,rot=Math.random()*20-10;
                h+='<span class="scatter-char" style="transform:translate('+tx+'px,'+ty+'px) rotate('+rot+'deg);opacity:'+(0.4+Math.random()*0.4)+'">'+ch+'</span>';
            });
            wrap.innerHTML=h;
            vb.style.opacity='1';

            vb.addEventListener('click',function(e){
                e.stopPropagation();
                var spans=this.querySelectorAll('.scatter-char');
                var fixed=spans.length&&spans[0].classList.contains('fixed');
                if(fixed){
                    var txt=this.getAttribute('data-t')||'';
                    var chs=txt.split('');
                    for(var si=chs.length-1;si>0;si--){var j=Math.floor(Math.random()*(si+1));var tmp=chs[si];chs[si]=chs[j];chs[j]=tmp;}
                    spans.forEach(function(sp,j){
                        var tx=Math.random()*60-30,ty=Math.random()*40-20,rot=Math.random()*20-10;
                        sp.classList.remove('fixed');
                        sp.style.transform='translate('+tx+'px,'+ty+'px) rotate('+rot+'deg)';
                        sp.style.opacity=0.4+Math.random()*0.4;
                        sp.textContent=chs[j]||'';
                    });
                } else {
                    var txt=this.getAttribute('data-t')||'';
                    spans.forEach(function(sp,j){
                        sp.classList.add('fixed');
                        sp.style.transform='translate(0,0) rotate(0deg)'; sp.style.opacity='1';
                        sp.textContent=txt[j]||'';
                        if(Math.random()>0.6) sp.classList.add('flicker');
                    });
                }
            });
        });
    }

    // ===== 星座逐一点亮 + 连线 =====
    function animateConstellation(el){
        var sky=el.querySelector('.const-sky');
        if(!sky) return;
        var cnt=parseInt(sky.getAttribute('data-cnt'))||0;
        var rem=parseInt(sky.getAttribute('data-rem'))||0;
        var stars=sky.querySelectorAll('.const-star');
        stars.forEach(function(s,i){
            if(i<cnt) setTimeout(function(){s.classList.add('on');},i*120);
            else if(i===cnt && rem>0) setTimeout(function(){s.classList.add('half');},i*120);
        });
        var lines=el.querySelectorAll('.const-sky svg line');
        lines.forEach(function(l,i){
            setTimeout(function(){l.classList.add('on');},i*120+60);
        });
    }

    function render(idx){
        var c=chars[idx];
        var th='';c.todos.forEach(function(t){th+='<div class="todo-line'+(t.d?' done':'')+'">'+(t.d?'✔ ':'○ ')+(t.d?'<s>'+t.t+'</s>':t.t)+'</div>';});

        var sid='as_'+Math.random().toString(36).substr(2,8);

        // 星尘
        var stars='';
        for(var si=0;si<20;si++){var s=Math.random()*1.5+1;stars+='<span style="top:'+(Math.random()*98+1)+'%;left:'+(Math.random()*98+1)+'%;--d:'+(s+2)+'s;width:'+s+'px;height:'+s+'px"></span>';}

        // 星座散点：10颗星坐标（不同位置）+ 连线顺序
        var constPos = [
            {x:12,y:65},{x:32,y:18},{x:55,y:72},{x:72,y:35},
            {x:50,y:8},{x:88,y:52},{x:62,y:88},{x:38,y:50},
            {x:22,y:28},{x:82,y:18}
        ];
        var litVal=Math.min(100,Math.abs(c.favNum));
        var fullCnt=Math.floor(litVal/10);
        var remainder=litVal%10;
        // 星星
        var starHtml='';
        for(var di=0;di<10;di++){
            var p=constPos[di];
            starHtml+='<span class="const-star" style="left:'+p.x+'%;top:'+p.y+'%;transition-delay:'+(di*120)+'ms">★</span>';
        }
        // 连线（相邻已亮）
        var lineHtml='';
        var lastLit=-1;
        for(var di=0;di<10;di++){
            if(di<fullCnt){
                if(lastLit>=0){
                    var p1=constPos[lastLit],p2=constPos[di];
                    lineHtml+='<line x1="'+p1.x+'%" y1="'+p1.y+'%" x2="'+p2.x+'%" y2="'+p2.y+'%" style="transition-delay:'+(lastLit*120+60)+'ms"/>';
                }
                lastLit=di;
            }
        }
        if(fullCnt===0) lineHtml='<line x1="50%" y1="50%" x2="50%" y2="50%" style="opacity:0"/>';

        var html='<div id="'+sid+'"><div class="aw"><div class="ap">'+
            '<div class="cf"><div class="env">'+
            '<div class="env-stars">'+stars+'</div>'+
            '<div class="env-flap"></div>'+
            '<div class="env-body">'+
            '<div class="env-seal"><div class="env-seal-inner">★</div></div>'+
            '<div class="env-to">✦ T O ✦</div>'+
            '<div class="env-to-name">'+(c.name||'???')+'</div>'+
            '</div></div></div>'+
            '<div class="if">'+
            '<div class="sky-header"><div class="sky-stars">'+stars+'</div>'+
            '<div class="sky-name">'+(c.name||'???')+'</div>'+
            '<div class="sky-sub">✦ C E L E S T I A L ✦</div></div>'+
            '<div class="parchment">';

        // 星辰轨迹（星座进度条）
        html+='<div class="s-title">✦ 星辰轨迹</div><div class="fv-box">';
        if(c.fav){
            html+='<div class="fv-hd"><span class="fv-stage">'+(c.favStage||'')+'</span><span style="font-size:.75em;color:#8a7a6a;">'+c.favNum+'/100'+(c.favDelta?' ('+c.favDelta+')':'')+'</span></div>';
            html+='<div class="const-box"><div class="const-sky" id="const_'+sid+'" data-cnt="'+fullCnt+'" data-rem="'+remainder+'">'+
            '<svg>'+lineHtml+'</svg>'+starHtml+'</div>'+
            '<div class="const-label">✦ 星命连线 ✦</div></div>';
            if(c.favReason) html+='<div class="fv-reason">'+c.favReason+'</div>';
        } else html+='<div class="fv-void" style="text-align:center;padding:6px;color:#999;font-style:italic;font-size:.8em;">尚未显现</div>';
        html+='</div>';

        // 内心低语（散乱→归位）
        html+='<div class="s-title">✧ 内心低语</div><div class="voices">';
        html+='<div class="voice-block v1" data-t="'+((c.id||'(无声)').replace(/"/g,'&quot;'))+'"><span class="vi">🌙</span><span class="scatter-wrap"></span></div>';
        html+='<div class="voice-block v2" data-t="'+((c.sup||'(无声)').replace(/"/g,'&quot;'))+'"><span class="vi">☀️</span><span class="scatter-wrap"></span></div>';
        html+='<div class="voice-block v3" data-t="'+((c.ego||'(权衡中)').replace(/"/g,'&quot;'))+'"><span class="vi">⚖️</span><span class="scatter-wrap"></span></div>';
        html+='</div>';

        // 秘仪
        if(c.und||c.phy){
            html+='<div class="s-title">◇ 秘仪</div><div class="priv-row">';
            if(c.und) html+='<span class="priv-tag">'+c.und+'</span>';
            if(c.phy) html+='<span class="priv-tag">'+c.phy+'</span>';
            html+='</div>';
        }

        // 命运簿
        if(c.todos.length){
            html+='<div class="s-title">📜 命运簿</div><div class="todo-box">'+th+'</div>';
        }

        // 星线纠缠
        if(c.bond){
            var bl=c.bond.split(/\n/).map(function(l){return l.trim()}).filter(Boolean);
            if(bl.length) html+='<div class="s-title">⚝ 星线纠缠</div><div class="bond-text">'+bl.join('<br>')+'</div>';
        }

        // 天命回响
        if(c.karma) html+='<div class="s-title">⌘ 天命回响</div><div class="bond-text">'+c.karma+'</div>';

        if(chars.length>1) html+='<div class="flip-btn" id="fp_'+sid+'">✦ 转星盘 · 换命轨 ✦</div>';
        html+='</div></div>';
        html+='</div></div>';

        var container=document.getElementById(containerId);
        if(container){
            container.innerHTML=html;
        } else {
            document.write('<div id="'+containerId+'">'+html+'</div>');
        }

        var ap=document.querySelector('#'+sid+' .ap');
        if(!ap) return;

        // 切换展开/折叠
        ap.addEventListener('click',function(e){
            if(e.target.closest('.flip-btn')) return;
            if(e.target.closest('.voice-block')) return;
            this.classList.toggle('cd');
            if(!this.classList.contains('cd')){
                setTimeout(function(){ animateConstellation(ap); }, 500);
            }
        });

        // 初始渲染：星座 + 文字散乱
        setTimeout(function(){
            animateConstellation(ap);
            scatterText(ap);
        }, 600);

        // 多角色翻页
        if(chars.length>1){
            var fp=document.getElementById('fp_'+sid);
            if(fp) fp.onclick=function(e){e.stopPropagation();curIdx=(curIdx+1)%chars.length;render(curIdx);};
        }
    }
    var containerId='astro_root_'+Math.random().toString(36).substr(2,6);
    render(0);
})();
</script>
</body>
</html>
