// ===== 记忆系统 v5.6 =====
// v5.6 修复：标记只在聊天加载时跑一次,对话中途不再更新(新出保护区的楼层不折叠、recall不跟随最新消息)；
//          加绑 MESSAGE_SENT / GENERATION_ENDED,每轮消息后重跑标记
//          总楼层显示改为"共N条(#0~#N-1楼)"——酒馆楼号从0起,总条数永远比最后一楼号大1,老被当成bug
// v5.5 修复：配置写在主页面window而脚本读iframe window导致设置不生效；配置改为localStorage持久化
var __memParentWin = window.parent && window.parent !== window ? window.parent : window;

function __getMemoryConfig() {
    // 优先读主页面上的即时配置（面板按钮写入），其次读持久化
    if (__memParentWin['__memoryConfig__']) return __memParentWin['__memoryConfig__'];
    try { return JSON.parse(__memParentWin.localStorage.getItem('wx_memory_config') || '{}'); } catch(e) { return {}; }
}

function __runMemory() {
    if (!window['__memoryBtnBound__']) {
        window['__memoryBtnBound__'] = true;
        try {
            eventOn(getButtonEvent('🧠记忆回溯'), function() { showMemoryPanel(); });
        } catch(e) {
            console.log('[记忆系统] 按钮绑定失败:', e);
        }
    }

    var context = window.SillyTavern.getContext();
    if (!context || !context.chat) return;

    var history = context.chat;
    var lastUserMsg = '';
    var lastAiMsg = '';
    for (var k = history.length - 1; k >= 0; k--) {
        if (!lastAiMsg && !history[k].is_user && history[k].mes) {
            lastAiMsg = history[k].mes;
        }
        if (!lastUserMsg && history[k].is_user && history[k].mes) {
            lastUserMsg = history[k].mes;
        }
        if (lastUserMsg && lastAiMsg) break;
    }
    var userQuery = lastUserMsg + ' ' + lastAiMsg;

    var config = __getMemoryConfig();
    var protectCount    = config.protectCount    || 20;
    var maxRecallLimit  = config.maxRecallLimit   || 14;
    var total = history.length;
    var recallCounter = 0;
    var plainCount = 0; // 保护区外无[Synopsis]的楼层(用户发言/无摘要AI楼),原文发送不参与折叠

    function hasFoldTag(mes)   { return mes.indexOf('<span data-rag="fold"')   === 0; }
    function hasRecallTag(mes) { return mes.indexOf('<span data-rag="recall"') === 0; }

    function stripTags(mes) {
        return mes
            .replace(/^<span data-rag="fold"[^>]*><\/span>/, '')
            .replace(/^<span data-rag="recall"[^>]*><\/span>/, '');
    }

    for (var i = total - protectCount - 1; i >= 0; i--) {
        var msg = history[i];
        if (!msg.mes) continue;
        var cleanMes = stripTags(msg.mes);

        var hasSummary = cleanMes.includes('[Synopsis]:');
        if (!hasSummary) {
            msg.mes = cleanMes;
            plainCount++;
            continue;
        }

        var kwMatch = cleanMes.match(/\[Keywords\]\s*:\s*\[\[\s*([\s\S]*?)\s*\]\]/);
        var isTriggered = false;
        if (kwMatch && kwMatch[1] && userQuery) {
            var keywords = kwMatch[1].split(/,|，/).map(function(k) { return k.trim(); }).filter(Boolean);
            isTriggered = keywords.some(function(k) { return k && userQuery.includes(k); });
        }

        if (isTriggered && recallCounter < maxRecallLimit) {
            msg.mes = '<span data-rag="recall" style="display:none"></span>' + cleanMes;
            recallCounter++;
        } else {
            msg.mes = '<span data-rag="fold" style="display:none"></span>' + cleanMes;
        }
    }

    var foldCount = 0;
    var recallList = [];
    for (var j = 0; j < history.length; j++) {
        var m = history[j];
        if (!m.mes) continue;
        if (hasFoldTag(m.mes)) foldCount++;
        if (hasRecallTag(m.mes)) {
            var synMatch = m.mes.match(/\[Synopsis\]:\s*([\s\S]*?)\s*(?=\[Keywords\]|<\/Narrative_Matrix>)/);
            var summary  = synMatch ? synMatch[1].trim() : '(无摘要)';
            var kw2      = m.mes.match(/\[Keywords\]\s*:\s*\[\[\s*([\s\S]*?)\s*\]\]/);
            var kwStr    = kw2 ? kw2[1] : '';
            var hitKeywords = [];
            if (kwStr && userQuery) {
                var allKw = kwStr.split(/,|，/).map(function(k){ return k.trim(); }).filter(Boolean);
                hitKeywords = allKw.filter(function(k){ return k && userQuery.includes(k); });
            }
            recallList.push({
                floor:       j,
                summary:     summary,
                keywords:    kwStr,
                hitKeywords: hitKeywords.length > 0 ? hitKeywords.join('、') : kwStr
            });
        }
    }

    window['__memoryState__'] = {
        total: total, protectCount: protectCount, plainCount: plainCount,
        maxRecallLimit: maxRecallLimit,
        recallCounter: recallCounter,
        foldCount: foldCount, recallList: recallList,
        userQuery: userQuery
    };

    function showMemoryPanel() {
        // 每次打开面板前重新运行一次标记逻辑，确保数据是最新的（切卡/新聊天后）
        __runMemory();
        $('#memory-status-panel').remove();
        // 注入手机端强制全屏 CSS（只注入一次）
        if (!$('#mem-mobile-fix').length) {
            $('<style id="mem-mobile-fix">').html(
                '@media (max-width: 768px) {' +
                '  #memory-status-panel {' +
                '    position: fixed !important; top: 0 !important; left: 0 !important;' +
                '    width: 100vw !important; height: 100vh !important; height: 100dvh !important;' +
                '    z-index: 100000 !important;' +
                '  }' +
                '  #memory-status-panel > .mem-panel {' +
                '    position: fixed !important; top: 0 !important; left: 0 !important;' +
                '    width: 100vw !important; height: 100vh !important; height: 100dvh !important;' +
                '    max-width: none !important; max-height: none !important;' +
                '    border-radius: 0 !important; margin: 0 !important;' +
                '    transform: none !important;' +
                '    z-index: 100001 !important;' +
                '  }' +
                '}'
            ).appendTo('head');
        }
        var s    = window['__memoryState__'] || {};
        var list = s.recallList || [];

        var html = '<div style="padding:16px;font-size:14px;line-height:1.7;color:#d8d4e8;">';
        html += '<div style="font-size:16px;font-weight:bold;margin-bottom:12px;">📊 记忆系统状态</div>';
        html += '<div>📌 总楼层：' + (s.total||0) + ' 条（#0 ~ #' + Math.max((s.total||0)-1, 0) + ' 楼，楼号从0起）</div>';
        html += '<div style="margin:8px 0;display:flex;flex-direction:column;gap:6px;">'
              + '<div style="display:flex;align-items:center;gap:6px;">⚙️ 只发送倒数 '
              + '<input id="mem-protect-input" type="number" min="1" max="50" value="' + (s.protectCount||20) + '" '
              + 'style="width:48px;background:rgba(255,255,255,0.08);border:1px solid rgba(140,130,200,.25);'
              + 'border-radius:4px;color:inherit;padding:2px 4px;font-size:13px;text-align:center;"> 层</div>'
              + '<div style="display:flex;align-items:center;gap:6px;">🔄 召回上限 '
              + '<input id="mem-recall-input" type="number" min="1" max="30" value="' + (s.maxRecallLimit||14) + '" '
              + 'style="width:48px;background:rgba(255,255,255,0.08);border:1px solid rgba(140,130,200,.25);'
              + 'border-radius:4px;color:inherit;padding:2px 4px;font-size:13px;text-align:center;"> 条</div>'
              + '<div style="display:flex;align-items:center;gap:8px;">'
              + '<button onclick="'
              + 'window[\'__memoryConfig__\']={protectCount:parseInt(document.getElementById(\'mem-protect-input\').value)||20,'
              + 'maxRecallLimit:parseInt(document.getElementById(\'mem-recall-input\').value)||14};'
              + 'try{localStorage.setItem(\'wx_memory_config\',JSON.stringify(window[\'__memoryConfig__\']));}catch(e){}'
              + 'document.getElementById(\'mem-config-tip\').style.display=\'inline\';" '
              + 'style="background:rgba(167,139,250,0.15);border:1px solid rgba(167,139,250,.4);border-radius:4px;'
              + 'color:#c4b5fd;font-size:12px;cursor:pointer;padding:4px 12px;">✅ 应用</button>'
              + '<span id="mem-config-tip" style="display:none;font-size:12px;opacity:0.6;">✓ 下次生成生效</span>'
              + '</div></div>';
        html += '<div>🛡️ 保护层：最近 '  + (s.protectCount||20) + ' 层</div>';
        html += '<div>🔁 本轮 Recall：'  + (s.recallCounter||0) + ' 条（含完整正文,下方只显示摘要）</div>';
        html += '<div>📦 已发送摘要：'   + (s.foldCount||0)     + ' 条（正文不发给AI）</div>';
        html += '<div>✏️ 无摘要楼层：'   + (s.plainCount||0)    + ' 条（用户发言等，原文发送）</div>';
        var protActual = Math.min(s.protectCount||0, s.total||0);
        html += '<div style="font-size:12px;opacity:0.55;">账目：保护 ' + protActual
              + ' + Recall ' + (s.recallCounter||0) + ' + 摘要 ' + (s.foldCount||0)
              + ' + 无摘要 ' + (s.plainCount||0) + ' = ' + (protActual+(s.recallCounter||0)+(s.foldCount||0)+(s.plainCount||0)) + ' / 共' + (s.total||0) + '条</div>';
        var allHitKw = [];
        list.forEach(function(it){ if(it.hitKeywords) allHitKw.push(it.hitKeywords); });
        html += '<div>🔑 命中关键词：<span style="opacity:0.7">' + (allHitKw.length > 0 ? allHitKw.join(' / ') : '无') + '</span></div>';


        if (list.length > 0) {
            html += '<div style="margin-top:12px;border-top:1px solid rgba(140,130,200,.25);padding-top:8px;">';
            html += '<div style="font-weight:bold;margin-bottom:8px;">✅ 本轮召回：</div>';
            for (var i = 0; i < list.length; i++) {
                var it     = list[i];
                var itemId = 'recall-item-' + i;
                html += '<div style="margin-bottom:8px;border-radius:8px;border:1px solid rgba(140,130,200,.2);overflow:hidden;">';
                html += '<div onclick="var c=document.getElementById(\'' + itemId + '\');c.style.display=c.style.display===\'none\'?\'block\':\'none\'" '
                      + 'style="padding:10px 12px;cursor:pointer;display:flex;justify-content:space-between;align-items:center;background:rgba(255,255,255,0.04);">';
                html += '<span style="color:#c4b5fd;font-size:13px;">第 ' + it.floor + ' 楼'
                      + '&nbsp;<span style="opacity:0.6;font-size:12px;">🔑 ' + it.hitKeywords + '</span></span>';
                html += '<span style="opacity:0.5;font-size:12px;">▼</span>';
                html += '</div>';
                html += '<div id="' + itemId + '" style="display:none;padding:10px 12px;font-size:13px;line-height:1.6;border-top:1px solid rgba(140,130,200,.2);">';
                html += it.summary.replace(/\n/g, '<br>');
                html += '</div>';
                html += '</div>';
            }
            html += '</div>';
        } else {
            html += '<div style="margin-top:12px;font-style:italic;opacity:0.6;">（本轮无关键词命中，所有摘要压缩发送）</div>';
        }
        html += '</div>';

        var overlay = $('<div id="memory-status-panel">').css({
            position:'fixed', top:'0', left:'0', width:'100%', height:'100%',
            background:'rgba(0,0,0,0.6)',
            zIndex:99999,
            overflowY:'auto',
            WebkitOverflowScrolling:'touch'
        });

        var panel = $('<div class="mem-panel">').css({
            width:'90%', maxWidth:'520px',
            background:'#1a1530',
            border:'1px solid rgba(140,130,200,.2)',
            borderRadius:'12px',
            boxShadow:'0 8px 32px rgba(0,0,0,0.6)',
            display:'flex', flexDirection:'column',
            overflow:'hidden', maxHeight:'90vh',
            position:'absolute', top:'50%', left:'50%',
            transform:'translate(-50%, -50%)'
        });

        var header = $('<div>').css({
            display:'flex', justifyContent:'space-between', alignItems:'center',
            padding:'12px 16px',
            background:'rgba(255,255,255,0.03)',
            borderBottom:'1px solid rgba(140,130,200,.2)'
        });
        header.append('<div style="font-weight:bold;font-size:16px;">🧠 记忆回溯</div>');
        $('<button>✕</button>').css({
            background:'none', border:'none',
            color:'#d8d4e8',
            fontSize:'18px', cursor:'pointer', padding:'0 4px'
        }).on('click', function(){ overlay.remove(); }).appendTo(header);
        panel.append(header);

        $('<div>').css({ flex:'1', overflowY:'auto', padding:'8px' })
                  .html(html).appendTo(panel);

        overlay.append(panel).appendTo($('body'));

        overlay.on('mousedown touchend', function(e){
            if (e.target === overlay[0]) overlay.remove();
        });
    }
}

// 修复: 脚本可能抢在聊天加载完成前运行(此时 chatLength 极小, 标记循环不执行导致记忆不生效)
// 监听聊天加载/切换完成事件, 届时重跑一次标记逻辑; 重跑是幂等的(每次先 stripTags 再重标记)
// v5.6: 再绑 MESSAGE_SENT(用户消息入库后、prompt组装前, 本轮生成即用新标记)和
//       GENERATION_ENDED(AI回复落地后), 否则标记冻结在聊天加载时的楼层数, 越聊越失效
if (!window['__memoryChatBound__']) {
    window['__memoryChatBound__'] = true;
    try {
        eventOn(tavern_events.CHAT_CHANGED,      function() { setTimeout(__runMemory, 100); });
        eventOn(tavern_events.MESSAGE_SENT,      function() { __runMemory(); });
        eventOn(tavern_events.GENERATION_ENDED,  function() { setTimeout(__runMemory, 100); });
    } catch (e) { console.log('[记忆系统] 聊天事件绑定失败:', e); }
}
__runMemory();

// ============================================================
// 美梦巡游·预设条目折叠系统 Ver.5
// CSS 按条目ID锁定隐藏：酒馆重渲染时条目一出生就被CSS藏住，防跳动/误触
// ============================================================

(function() {

const parentWin = window.parent && window.parent !== window ? window.parent : window;
const document = parentWin.document;

(function initPromptFolding() {
  const INSTANCE_ID = Date.now() + '_' + Math.random();
  const FOLD_KEY   = 'wx_fold_states';
  const FOLD_ON    = 'wx_fold_enabled';
  const LIST_SEL   = '#completion_prompt_manager_list';
  const ITEM_SEL   = 'li[data-pm-identifier]';
  const NAME_SEL   = '[data-pm-name]';

  const FOLD_GROUPS = [
    { s: '╔💠头部💠╗',   e: '╚💠END💠╝',   label: '✧💠头部💠✧' },
    { s: '╔🌆入梦🌆╗',   e: '╚🌆END🌆╝',   label: '✧🌆入梦🌆✧' },
    { s: '╔📖文风📖╗',   e: '╚📖END📖╝',   label: '✧📖文风📖✧' },
    { s: '╔⚙️设置⚙️╗', e: '╚⚙️END⚙️╝', label: '✧⚙️设置⚙️✧' },
    { s: '╔💕好感💕╗',   e: '╚💕END💕╝',   label: '✧💕好感💕✧' },
    { s: '╔📌默认📌╗',   e: '╚📌END📌╝',   label: '✧📌默认📌✧' },
    { s: '╔🔧通病🔧╗',   e: '╚🔧END🔧╝',   label: '✧🔧通病🔧✧' },
    { s: '╔📋必开📋╗',   e: '╚📋END📋╝',   label: '✧📋必开📋✧' },
    { s: '╔🧩状态🧩╗',   e: '╚🧩END🧩╝',   label: '✧🧩状态🧩✧' },
    { s: '╔🎪剧场🎪╗',   e: '╚🎪END🎪╝',   label: '✧🎪剧场🎪✧' },
    { s: '╔🧠记忆🧠╗',   e: '╚🧠END🧠╝',   label: '✧🧠记忆🧠✧' },
    { s: '╔💭思考💭╗',   e: '╚💭END💭╝',   label: '✧💭思考💭✧' },
    { s: '╔💠尾部💠╗',   e: '╚💠END💠╝',   label: '✧💠尾部💠✧', last: true },
  ];

  // 状态实时读写 localStorage，避免脚本重载后新旧实例状态不一致
  const isEnabled = () => parentWin.localStorage.getItem(FOLD_ON) !== 'false';
  const setEnabled = v => parentWin.localStorage.setItem(FOLD_ON, v ? 'true' : 'false');
  const getStates = () => { try { return JSON.parse(parentWin.localStorage.getItem(FOLD_KEY) || '{}'); } catch(_) { return {}; } };
  const saveStates = s => parentWin.localStorage.setItem(FOLD_KEY, JSON.stringify(s));

  function getName(li) {
    const el = li.querySelector(NAME_SEL);
    return el ? el.dataset.pmName : '';
  }

  function parseSections(list) {
    const items = [...list.querySelectorAll(ITEM_SEL)];
    const sections = [];
    let i = 0;
    while (i < items.length) {
      const name = getName(items[i]);
      const group = FOLD_GROUPS.find(g => g.s === name);
      if (group) {
        const startIdx = i;
        let endIdx = -1;
        if (group.last) {
          for (let j = items.length - 1; j > startIdx; j--) {
            if (getName(items[j]) === group.e) { endIdx = j; break; }
          }
        } else {
          for (let j = startIdx + 1; j < items.length; j++) {
            if (getName(items[j]) === group.e) { endIdx = j; break; }
          }
        }
        if (endIdx > startIdx) {
          const inner = items.slice(startIdx + 1, endIdx + 1);
          sections.push({
            headerLi: items[startIdx],
            key: group.s,
            label: group.label,
            inner: inner,
            count: inner.filter(x => !getName(x).startsWith('╔') && !getName(x).startsWith('╚') && !getName(x).startsWith('--')).length,
          });
          i = endIdx + 1;
          continue;
        }
      }
      i++;
    }
    return sections;
  }

  // ── 静态样式（头部外观） ─────────────────────────────────
  const FOLD_CSS_ID = 'wx-fold-css';
  function ensureCSS() {
    if (document.getElementById(FOLD_CSS_ID)) return;
    const style = document.createElement('style');
    style.id = FOLD_CSS_ID;
    style.textContent = '\
      .wx-fold-header { cursor: pointer !important; position: relative; user-select: none; }\
      .wx-fold-header:hover { background: rgba(140,130,200,.08) !important; }\
      .wx-fold-header .prompt_manager_prompt_controls { display: none !important; }\
      .wx-fold-header .prompt_manager_prompt_tokens { display: none !important; }\
      .wx-fold-header .completion_prompt_manager_prompt_name { pointer-events: none; }\
      .wx-fold-badge { font-size: 11px; opacity: .55; margin-left: 6px; pointer-events: none; }\
      .wx-fold-arrow { display: inline-block; font-size: 10px; margin-right: 3px; transition: transform .2s; }\
      .wx-fold-arrow.wx-open { transform: rotate(90deg); }\
    ';
    document.head.appendChild(style);
  }

  // ── 动态样式：按条目ID隐藏（核心防跳动机制） ──────────────
  // 重渲染出来的 li 带同样的 data-pm-identifier，CSS 即时命中，
  // 不需要等脚本跑，布局始终稳定。
  const DYN_CSS_ID = 'wx-fold-dyn-css';
  function cssEscape(s) {
    return (parentWin.CSS && parentWin.CSS.escape) ? parentWin.CSS.escape(s) : String(s).replace(/["\\]/g, '\\$&');
  }
  function updateHiddenCSS(hiddenIds) {
    let style = document.getElementById(DYN_CSS_ID);
    if (!style) {
      style = document.createElement('style');
      style.id = DYN_CSS_ID;
      document.head.appendChild(style);
    }
    if (!hiddenIds.length) { style.textContent = ''; return; }
    const sel = hiddenIds.map(id => LIST_SEL + ' li[data-pm-identifier="' + cssEscape(id) + '"]').join(',');
    style.textContent = sel + ' { display: none !important; }';
  }

  function pauseObserver() { observer.disconnect(); }
  function resumeObserver() {
    const target = document.querySelector('#completion_prompt_manager');
    if (target) observer.observe(target, { childList: true, subtree: false });
  }

  function applyFolding(list) {
    pauseObserver();
    ensureCSS();

    if (!isEnabled()) {
      updateHiddenCSS([]);
      list.querySelectorAll('.wx-fold-header').forEach(el => {
        el.classList.remove('wx-fold-header');
        const arrow = el.querySelector('.wx-fold-arrow');
        if (arrow) arrow.remove();
        const badge = el.querySelector('.wx-fold-badge');
        if (badge) badge.remove();
        const linkEl = el.querySelector('[data-wx-orig-text]');
        if (linkEl) { linkEl.textContent = linkEl.dataset.wxOrigText; delete linkEl.dataset.wxOrigText; }
      });
      resumeObserver();
      return;
    }

    const states = getStates();
    const sections = parseSections(list);

    // 第一步：先更新隐藏CSS（最关键，瞬时生效，布局立即稳定）
    const hiddenIds = [];
    for (const sec of sections) {
      if (states[sec.key] !== false) {
        for (const li of sec.inner) hiddenIds.push(li.dataset.pmIdentifier);
      }
    }
    updateHiddenCSS(hiddenIds);

    // 第二步：装饰头部（纯外观，迟一点也不影响布局稳定）
    for (const sec of sections) {
      const folded = states[sec.key] !== false;
      const hdr = sec.headerLi;
      hdr.classList.add('wx-fold-header');

      const nameSpan = hdr.querySelector('.completion_prompt_manager_prompt_name');
      if (!nameSpan) continue;
      const linkEl = nameSpan.querySelector('a.prompt-manager-inspect-action') || nameSpan.querySelector('span[title]');

      if (folded) {
        if (linkEl && !linkEl.dataset.wxOrigText) linkEl.dataset.wxOrigText = linkEl.textContent;
        if (linkEl) linkEl.textContent = sec.label;
      } else {
        if (linkEl && linkEl.dataset.wxOrigText) {
          linkEl.textContent = linkEl.dataset.wxOrigText;
          delete linkEl.dataset.wxOrigText;
        }
      }

      let arrow = hdr.querySelector('.wx-fold-arrow');
      if (!arrow) {
        arrow = document.createElement('span');
        arrow.className = 'wx-fold-arrow';
        nameSpan.prepend(arrow);
      }
      arrow.textContent = '▶';
      arrow.classList.toggle('wx-open', !folded);

      let badge = hdr.querySelector('.wx-fold-badge');
      if (!badge) {
        badge = document.createElement('span');
        badge.className = 'wx-fold-badge';
        nameSpan.appendChild(badge);
      }
      badge.textContent = folded ? ' (' + sec.count + '条)' : '';
    }
    resumeObserver();
  }

  function ensureToggleBtn(list) {
    const container = list.parentElement;
    if (!container) return;
    let btn = container.querySelector('#wx-fold-toggle');
    // 旧脚本实例留下的按钮带着失效的监听器，发现不是本实例创建的就重建
    if (btn && btn.__wxOwner !== INSTANCE_ID) { btn.remove(); btn = null; }
    if (btn) {
      btn.textContent = isEnabled() ? '📂 取消折叠' : '📁 折叠条目';
      return;
    }
    btn = document.createElement('button');
    btn.id = 'wx-fold-toggle';
    btn.__wxOwner = INSTANCE_ID;
    btn.style.cssText = 'display:inline-flex;align-items:center;gap:4px;margin:6px 4px;padding:3px 10px;font-size:12px;border:1px solid rgba(140,130,200,.3);background:rgba(130,120,200,.1);color:#a78bfa;border-radius:6px;cursor:pointer;';
    btn.textContent = isEnabled() ? '📂 取消折叠' : '📁 折叠条目';
    btn.addEventListener('click', () => {
      setEnabled(!isEnabled());
      btn.textContent = isEnabled() ? '📂 取消折叠' : '📁 折叠条目';
      const l = document.querySelector(LIST_SEL);
      if (l) applyFolding(l);
    });
    container.insertBefore(btn, list);
  }

  // 移除旧实例的全局点击监听，避免重复触发互相抵消
  if (parentWin.__wxFoldClickHandler) {
    document.removeEventListener('click', parentWin.__wxFoldClickHandler, true);
  }
  const clickHandler = (e) => {
    if (!isEnabled()) return;
    const li = e.target.closest('.wx-fold-header');
    if (!li) return;

    const key = FOLD_GROUPS.find(g => g.s === getName(li))?.s;
    if (!key) return;

    e.stopPropagation();
    e.preventDefault();
    const states = getStates();
    states[key] = (states[key] === false) ? true : false;
    saveStates(states);
    const list = document.querySelector(LIST_SEL);
    if (list) applyFolding(list);
  };
  parentWin.__wxFoldClickHandler = clickHandler;
  document.addEventListener('click', clickHandler, true);

  // 断开旧实例的观察器，否则它会用过期状态把界面改回去
  if (parentWin.__wxFoldObserver) {
    try { parentWin.__wxFoldObserver.disconnect(); } catch(_){}
  }
  let debounceTimer = null;
  const observer = new MutationObserver(() => {
    if (debounceTimer) return;
    debounceTimer = setTimeout(() => {
      debounceTimer = null;
      const list = document.querySelector(LIST_SEL);
      if (!list || list.children.length < 3) return;
      ensureToggleBtn(list);
      applyFolding(list);
    }, 100);
  });
  parentWin.__wxFoldObserver = observer;

  function boot() {
    const target = document.querySelector('#completion_prompt_manager');
    if (target) {
      observer.observe(target, { childList: true, subtree: false });
    } else {
      const bodyObs = new MutationObserver(() => {
        const t = document.querySelector('#completion_prompt_manager');
        if (t) { bodyObs.disconnect(); observer.observe(t, { childList: true, subtree: false }); }
      });
      bodyObs.observe(document.body, { childList: true, subtree: true });
    }
    const list = document.querySelector(LIST_SEL);
    if (list && list.children.length > 3) {
      ensureToggleBtn(list);
      applyFolding(list);
    }
  }

  // readyState 为 interactive 时 DOMContentLoaded 可能已经错过，
  // 只要不是 loading 就直接启动，否则脚本会永远等不到事件而失效
  if (document.readyState !== 'loading') boot();
  else document.addEventListener('DOMContentLoaded', boot);

  console.log('[美梦巡游] 条目折叠系统 Ver.5 已加载');
})();

