// 解决：切换API时预设重载导致预设正则二次加载、可能损坏聊天记录
// 单按钮「📦正则搬运」弹出菜单：入全局 / 回预设 / 一键开关
// ============================================================

(function() {

const parentWin = window.parent && window.parent !== window ? window.parent : window;
const doc = parentWin.document;

const MARK = '梦游'; // 识别我们的正则：名字里带这个词
const SNAP_KEY = 'wx_regex_enabled_snapshot';

function notify(msg, type) {
  try { toastr[type || 'success'](msg, '正则搬运工'); } catch(_) { console.log('[正则搬运工]', msg); }
}

async function moveToGlobal() {
  try {
    // 1) 正则
    const presetRegexes = getTavernRegexes({ type: 'preset', name: 'in_use' });
    const rIds = new Set(presetRegexes.map(r => r.id));
    if (presetRegexes.length) {
      const globalRegexes = getTavernRegexes({ type: 'global' });
      const merged = globalRegexes.filter(r => !rIds.has(r.id)).concat(presetRegexes);
      await replaceTavernRegexes(merged, { type: 'global' });
      await replaceTavernRegexes([], { type: 'preset', name: 'in_use' });
    }
    // 2) 脚本（补充②：让用户对脚本的修改在切换预设时不丢失）
    const scriptCount = await moveScriptsToGlobal();
    if (!presetRegexes.length && !scriptCount) {
      notify('当前预设里没有正则和脚本，无需搬运', 'info');
      return;
    }
    notify('已搬到全局：' + presetRegexes.length + ' 条正则 + ' + scriptCount + ' 个脚本，预设已清空。\n切换API不会再二次加载/丢改动了～');
  } catch (e) {
    notify('搬运失败：' + e.message, 'error');
    console.error('[正则搬运工]', e);
  }
}

// 把预设脚本搬到全局：先复制+打来源标记，再延迟清空预设（避免拆掉正在运行的自己）
async function moveScriptsToGlobal() {
  if (typeof getScriptTrees !== 'function' || typeof replaceScriptTrees !== 'function') return 0;
  const presetScripts = getScriptTrees({ type: 'preset' });
  if (!presetScripts.length) return 0;
  const tagged = presetScripts.map(t => {
    const d = Object.assign({}, t.data || {}, { __wxOrigin: 'preset' });
    return Object.assign({}, t, { data: d });
  });
  const ids = new Set(tagged.map(t => t.id));
  const globalScripts = getScriptTrees({ type: 'global' });
  const merged = globalScripts.filter(t => !ids.has(t.id)).concat(tagged);
  await replaceScriptTrees(merged, { type: 'global' });
  // 延迟清空预设脚本：让当前点击逻辑/提示先跑完，再拆预设里的脚本(含本脚本)
  setTimeout(() => {
    try { replaceScriptTrees([], { type: 'preset' }); }
    catch (e) { console.error('[正则搬运工] 清空预设脚本失败', e); }
  }, 800);
  return tagged.length;
}

// 把全局里"来源=preset"的脚本搬回预设：按 data 标记筛，不靠名字
async function moveScriptsBackToPreset() {
  if (typeof getScriptTrees !== 'function' || typeof replaceScriptTrees !== 'function') return 0;
  const globalScripts = getScriptTrees({ type: 'global' });
  const ours = globalScripts.filter(t => t && t.data && t.data.__wxOrigin === 'preset');
  if (!ours.length) return 0;
  const ids = new Set(ours.map(t => t.id));
  const cleaned = ours.map(t => {
    const d = Object.assign({}, t.data || {}); delete d.__wxOrigin;
    return Object.assign({}, t, { data: d });
  });
  const presetScripts = getScriptTrees({ type: 'preset' });
  const merged = presetScripts.filter(t => !ids.has(t.id)).concat(cleaned);
  await replaceScriptTrees(merged, { type: 'preset' });
  // 延迟清理全局里这些脚本（同样避免拆掉正在运行的自己）
  setTimeout(() => {
    try {
      const g = getScriptTrees({ type: 'global' });
      replaceScriptTrees(g.filter(t => !(t && t.data && t.data.__wxOrigin === 'preset')), { type: 'global' });
    } catch (e) { console.error('[正则搬运工] 清理全局脚本失败', e); }
  }, 800);
  return cleaned.length;
}

async function moveBackToPreset() {
  try {
    // 1) 正则（仍按名字含"梦游"识别）
    const globalRegexes = getTavernRegexes({ type: 'global' });
    const ours = globalRegexes.filter(r => (r.script_name || '').includes(MARK));
    const ids = new Set(ours.map(r => r.id));
    if (ours.length) {
      const presetRegexes = getTavernRegexes({ type: 'preset', name: 'in_use' });
      const merged = presetRegexes.filter(r => !ids.has(r.id)).concat(ours);
      await replaceTavernRegexes(merged, { type: 'preset', name: 'in_use' });
      await replaceTavernRegexes(globalRegexes.filter(r => !ids.has(r.id)), { type: 'global' });
    }
    // 2) 脚本（按 data 标记识别）
    const scriptCount = await moveScriptsBackToPreset();
    if (!ours.length && !scriptCount) {
      notify('全局里没有找到本预设搬出去的正则/脚本', 'info');
      return;
    }
    notify('已搬回预设：' + ours.length + ' 条正则 + ' + scriptCount + ' 个脚本。\n现在可以导出预设分发了～');
  } catch (e) {
    notify('搬运失败：' + e.message, 'error');
    console.error('[正则搬运工]', e);
  }
}

// 一键开关全局里的梦游正则（用别的预设时关掉，防卡顿）
// 快照式：关闭时记住哪些原本开着，再打开时只恢复那些（不会误开故意禁用的正则）
async function toggleGlobalRegexes() {
  try {
    const globalRegexes = getTavernRegexes({ type: 'global' });
    const ours = globalRegexes.filter(r => (r.script_name || '').includes(MARK));
    if (!ours.length) {
      notify('全局里没有找到带"' + MARK + '"的正则（先按📤搬过去）', 'info');
      return;
    }
    const anyEnabled = ours.some(r => r.enabled);
    if (anyEnabled) {
      const snapshot = ours.filter(r => r.enabled).map(r => r.id);
      parentWin.localStorage.setItem(SNAP_KEY, JSON.stringify(snapshot));
      await updateTavernRegexesWith(regexes => {
        regexes.forEach(r => { if ((r.script_name || '').includes(MARK)) r.enabled = false; });
        return regexes;
      }, { type: 'global' });
      notify('已关闭 ' + snapshot.length + ' 条梦游正则。\n用别的预设去吧，回来再按一次恢复～');
    } else {
      let snapshot = null;
      try { snapshot = JSON.parse(parentWin.localStorage.getItem(SNAP_KEY) || 'null'); } catch(_){}
      const snapSet = snapshot ? new Set(snapshot) : null;
      let count = 0;
      await updateTavernRegexesWith(regexes => {
        regexes.forEach(r => {
          if (!(r.script_name || '').includes(MARK)) return;
          let restore = snapSet ? snapSet.has(r.id) : true;
          if (!snapSet && /^wx-header-/.test(r.id)) {
            const helper = getVariables({ type: 'script', script_id: '00ea2469-afb2-4d06-be02-65bb89b9e474' });
            restore = r.id === 'wx-header-' + (helper.headerStyle || 'specimen');
          }
          if (restore) { r.enabled = true; count++; }
        });
        return regexes;
      }, { type: 'global' });
      notify('已恢复 ' + count + ' 条梦游正则，欢迎回来～');
    }
  } catch (e) {
    notify('开关失败：' + e.message, 'error');
    console.error('[正则搬运工]', e);
  }
}

// ── 弹出菜单 ─────────────────────────────────────────────
const MENU_ID = 'wx-regex-menu';

function closeMenu() {
  const m = doc.getElementById(MENU_ID);
  if (m) m.remove();
}

function showMenu() {
  if (doc.getElementById(MENU_ID)) { closeMenu(); return; }
  const overlay = doc.createElement('div');
  overlay.id = MENU_ID;
  const vw = parentWin.innerWidth, vh = parentWin.innerHeight;
  overlay.style.cssText = 'position:fixed;top:0;left:0;width:' + vw + 'px;height:' + vh + 'px;z-index:99999;background:rgba(0,0,0,.45);';
  const box = doc.createElement('div');
  const boxW = Math.min(280, Math.floor(vw * 0.88));
  box.style.cssText = 'position:absolute;background:#161225;border:1px solid rgba(140,130,200,.3);border-radius:12px;padding:18px 20px;width:' + boxW + 'px;max-height:' + Math.floor(vh * 0.8) + 'px;overflow-y:auto;box-shadow:0 12px 40px rgba(0,0,0,.5);box-sizing:border-box;';
  box.innerHTML =
    '<div style="font-size:14px;font-weight:600;color:#e2dff0;margin-bottom:4px;">📦 正则·脚本搬运工</div>' +
    '<div style="font-size:11px;color:#8b86a3;margin-bottom:12px;line-height:1.5;">防止切换API时预设正则/脚本二次加载、改动丢失</div>';
  const mkBtn = (label, desc, fn) => {
    const b = doc.createElement('button');
    b.style.cssText = 'display:block;width:100%;text-align:left;margin-bottom:8px;padding:10px 12px;border:1px solid rgba(140,130,200,.25);background:rgba(130,120,200,.08);color:#c9c4e0;border-radius:8px;cursor:pointer;font-size:13px;';
    b.innerHTML = label + '<div style="font-size:10.5px;color:#8b86a3;margin-top:2px;">' + desc + '</div>';
    b.addEventListener('click', () => { closeMenu(); fn(); });
    box.appendChild(b);
  };
  mkBtn('📤 正则+脚本入全局', '正则和脚本都搬到全局（日常推荐，换API不丢改动）', moveToGlobal);
  mkBtn('📥 正则+脚本回预设', '搬回预设（导出分发预设之前用）', moveBackToPreset);
  mkBtn('🔛 梦游正则开关', '一键关闭/恢复全局里的梦游正则', toggleGlobalRegexes);
  overlay.addEventListener('click', e => { if (e.target === overlay) closeMenu(); });
  overlay.appendChild(box);
  doc.body.appendChild(overlay);
  // 渲染后实测尺寸，用像素居中（不依赖百分比，避免移动端布局被插件改坏）
  const bw = box.offsetWidth, bh = box.offsetHeight;
  box.style.left = Math.max(8, Math.floor((vw - bw) / 2)) + 'px';
  box.style.top  = Math.max(8, Math.floor((vh - bh) / 2)) + 'px';
}

eventOn(getButtonEvent('📦正则搬运'), showMenu);

console.log('[美梦巡游] 正则搬运工已加载');
})();

