#wx-overlay.wx-visible {
  opacity: 1; pointer-events: auto;
}
#wx-panel {
  background: var(--wx-bg, #161225);
  border: 1px solid var(--wx-border, rgba(140,130,200,.2));
  border-radius: 12px;
  width: 90%; max-width: 520px;
  max-height: 88vh;
  max-height: 88dvh;
  display: flex; flex-direction: column;
  overflow: hidden;
  box-shadow: 0 16px 48px rgba(0,0,0,.5);
  margin: auto;  /* flex 容器内水平垂直居中,超高时贴边不越界 */
  transform: scale(.95);
  transition: transform .2s;
}
#wx-overlay.wx-visible #wx-panel { transform: scale(1); }

.wx-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: 14px 18px 12px;
  border-bottom: 1px solid var(--wx-border);
  background: rgba(255,255,255,.03);
  flex-shrink: 0;
}
.wx-header-title {
  font-size: .95em; font-weight: 600;
  color: var(--wx-text);
  letter-spacing: .02em;
}
.wx-close {
  background: none; border: none;
  color: var(--wx-text2);
  cursor: pointer; font-size: 1.1em;
  opacity: .6; padding: 2px 6px; border-radius: 6px;
  transition: opacity .15s, background .15s;
}
.wx-close:hover { opacity: 1; background: var(--wx-bg3); }

/* 模型分页 */
.wx-tabs {
  display: flex; gap: 2px; padding: 10px 10px 0;
  border-bottom: 1px solid var(--wx-border);
  flex-shrink: 0;
  overflow-x: auto; flex-wrap: nowrap;  /* 放不下就横向滑,标签永不折行 */
  scrollbar-width: none;
}
.wx-tabs::-webkit-scrollbar { display: none; }
.wx-tab {
  padding: 6px 10px; border-radius: 8px 8px 0 0;
  background: none; border: none;
  color: var(--wx-text2);
  font-size: .82em; font-weight: 500;
  cursor: pointer; transition: all .15s;
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  white-space: nowrap; flex-shrink: 0;  /* 文字不许在按钮里换行 */
}
.wx-tab:hover { color: var(--wx-text); background: var(--wx-bg2); }
.wx-tab.wx-active {
  color: var(--wx-accent);
  border-bottom-color: var(--wx-accent);
  background: rgba(167,139,250,.1);
}

/* 内容区 */
.wx-body {
  flex: 1 1 auto; overflow-y: auto; padding: 14px 16px;
  min-height: 0;
}
.wx-body::-webkit-scrollbar { width: 4px; }
.wx-body::-webkit-scrollbar-thumb { background: rgba(255,255,255,.12); border-radius: 2px; }

/* 预设方案列表 */
.wx-profile-list { display: flex; flex-direction: column; gap: 8px; }

.wx-profile-item {
  display: flex; flex-direction: column; gap: 6px;
  padding: 10px 12px;
  border: 1px solid var(--wx-border, rgba(140,130,200,.2));
  border-radius: 10px;
  background: rgba(255,255,255,.03);
  transition: all .15s;
}
.wx-profile-item:hover { background: rgba(255,255,255,.06); }
.wx-profile-item.wx-active-profile {
  border-color: var(--wx-accent, #a78bfa);
  background: rgba(125,181,240,.07);
}

.wx-profile-top { min-width: 0; }
.wx-profile-name {
  font-size: .88em; font-weight: 600;
  color: var(--wx-text, #d8d4e8);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.wx-profile-meta {
  font-size: .74em; color: var(--wx-text2, #9590b0);
  margin-top: 2px;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}

.wx-profile-actions { display: flex; gap: 8px; align-items: center; }

/* ⭐ 默认星 */
.wx-star-btn {
  background: none; border: none; cursor: pointer;
  font-size: 1em; padding: 2px 4px; border-radius: 5px;
  transition: transform .15s;
  color: var(--wx-text2, #9590b0);
  opacity: .55;
}
.wx-star-btn.wx-starred { color: #f4c542; opacity: 1; }
.wx-globe-btn {
  background: none; border: none; cursor: pointer;
  font-size: 1em; padding: 2px 4px; border-radius: 5px;
  transition: transform .15s;
  color: var(--wx-text2, #9590b0);
  opacity: .35;
}
.wx-globe-btn.wx-globe-active { color: #4fc3f7; opacity: 1; }
.wx-globe-btn:hover { transform: scale(1.2); opacity: 1; }
.wx-globe-btn.wx-globe-disabled { pointer-events: none; opacity: .15; }
.wx-star-btn:hover { transform: scale(1.2); opacity: 1; }

/* 操作按钮 */
.wx-btn {
  padding: 5px 12px; border-radius: 7px;
  border: 1px solid var(--wx-border, rgba(140,130,200,.2));
  background: rgba(255,255,255,.06);
  color: var(--wx-text, #d8d4e8);
  font-size: .78em; font-weight: 500;
  cursor: pointer; transition: all .15s; white-space: nowrap;
}
.wx-btn:hover { background: rgba(255,255,255,.12); border-color: rgba(255,255,255,.25); }
.wx-btn.wx-btn-primary {
  background: var(--wx-accent, #a78bfa);
  border-color: transparent; color: #fff;
}
.wx-btn.wx-btn-primary:hover { filter: brightness(1.12); }
.wx-btn.wx-btn-apply {
  background: rgba(72,187,120,.15);
  border-color: rgba(72,187,120,.35);
  color: #48bb78;
}
.wx-btn.wx-btn-apply:hover { background: rgba(72,187,120,.25); }
.wx-btn.wx-btn-danger {
  background: rgba(245,101,101,.1);
  border-color: rgba(245,101,101,.25);
  color: #f56565;
}
.wx-btn.wx-btn-danger:hover { background: rgba(245,101,101,.2); }
/* emoji icon buttons */
.wx-icon-btn {
  background: none; border: none; cursor: pointer;
  font-size: 16px; padding: 2px 4px; min-width: 0;
  opacity: .8; transition: opacity .15s, transform .15s;
}
.wx-icon-btn:hover { opacity: 1; transform: scale(1.2); }
.wx-icon-btn.wx-icon-danger:hover { filter: brightness(1.3); }
/* legend */
.wx-legend {
  font-size: 11px; color: rgba(255,255,255,.45); text-align: center;
  padding: 4px 0 2px; letter-spacing: 1px;
}
#wx-panel.wx-day .wx-legend { color: rgba(0,0,0,.4); }

/* 工具栏 */
.wx-toolbar {
  display: flex; justify-content: space-between; align-items: center;
  margin-bottom: 12px; gap: 8px; flex-wrap: wrap;
}
.wx-toolbar-left { display: flex; gap: 6px; }

/* 分隔线 */
.wx-divider {
  margin: 14px 0 10px;
  position: relative; text-align: center;
}
.wx-divider::before {
  content: ''; position: absolute;
  left: 0; right: 0; top: 50%;
  border-top: 1px dashed var(--wx-border, rgba(140,130,200,.2));
}
.wx-divider span {
  position: relative; z-index: 1;
  background: var(--wx-bg, #161225);
  padding: 0 10px;
  font-size: .72em; color: var(--wx-text2, #9590b0);
  letter-spacing: .06em;
}

/* 大总结区 */
.wx-summary-section {
  border: 1px solid rgba(255,180,0,.18);
  border-radius: 10px;
  background: rgba(255,180,0,.04);
  padding: 10px 12px;
}
.wx-summary-label {
  font-size: .78em; font-weight: 600;
  color: #f4c542; margin-bottom: 8px;
  display: flex; align-items: center; gap: 6px;
}

/* 设置区 */
.wx-settings-section {
  border: 1px solid var(--wx-border, rgba(140,130,200,.2));
  border-radius: 10px; padding: 12px 14px; margin-bottom: 10px;
}
.wx-settings-title {
  font-size: .78em; font-weight: 600;
  color: var(--wx-accent, #a78bfa);
  margin-bottom: 10px; letter-spacing: .04em; text-transform: uppercase;
}

/* 输入框 */
.wx-input, .wx-textarea {
  width: 100%; border-radius: 7px;
  border: 1px solid var(--wx-border, rgba(140,130,200,.2));
  background: rgba(0,0,0,.25);
  color: var(--wx-text, #d8d4e8);
  padding: 7px 10px; font-size: .84em;
  box-sizing: border-box;
  transition: border-color .15s;
}
.wx-input:focus, .wx-textarea:focus {
  outline: none;
  border-color: var(--wx-accent, #a78bfa);
}
.wx-textarea { resize: vertical; min-height: 70px; }

.wx-label {
  font-size: .76em; color: var(--wx-text2, #9590b0);
  margin-bottom: 5px; display: block; font-weight: 500;
}

.wx-form-row { margin-bottom: 10px; }
.wx-form-row:last-child { margin-bottom: 0; }

/* 按钮组选择 */
.wx-btn-group {
  display: flex; flex-wrap: wrap; gap: 6px; margin-top: 4px;
}
.wx-option-btn {
  padding: 5px 11px; border-radius: 7px;
  border: 1px solid var(--wx-border, rgba(140,130,200,.2));
  background: rgba(255,255,255,.05);
  color: var(--wx-text2, #9590b0);
  font-size: .79em; cursor: pointer; transition: all .15s;
}
.wx-option-btn:hover { background: rgba(255,255,255,.1); color: var(--wx-text, #d8d4e8); }
.wx-option-btn.wx-selected {
  background: rgba(125,181,240,.18);
  border-color: var(--wx-accent, #a78bfa);
  color: var(--wx-accent, #a78bfa);
  font-weight: 600;
}

/* 字数行 */
.wx-wordcount-row {
  display: flex; gap: 8px; align-items: center;
}
.wx-wordcount-row .wx-input { flex: 1; }
.wx-wordcount-row span { font-size: .8em; color: var(--wx-text2, #9590b0); white-space: nowrap; }

/* 档案设置行 */
.wx-archive-row {
  display: flex; gap: 10px; align-items: center; flex-wrap: wrap;
}
.wx-archive-row label { font-size: .78em; color: var(--wx-text2, #9590b0); }
.wx-archive-row .wx-input { width: 100px; }

/* 全局预设状态 */
.wx-global-status {
  padding: 6px 10px; margin-bottom: 8px;
  border: 1px solid var(--wx-border, rgba(140,130,200,.2));
  border-radius: 8px; font-size: 13px;
  background: var(--wx-bg2, rgba(130,120,200,.08));
}

/* 模型折叠区 */
.wx-model-section {
  border: 1px solid var(--wx-border, rgba(140,130,200,.2));
  border-radius: 10px; margin-bottom: 8px; overflow: hidden;
}
.wx-model-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: 8px 12px; cursor: pointer;
  background: rgba(255,255,255,.03);
  transition: background .15s;
}
.wx-model-header:hover { background: rgba(255,255,255,.06); }
.wx-model-header-left {
  display: flex; align-items: center; gap: 8px;
  font-size: .85em; font-weight: 600;
  color: var(--wx-text, #d8d4e8);
}
.wx-model-header-star {
  font-size: .75em; color: #f4c542;
}
.wx-model-header-arrow {
  font-size: .7em; color: var(--wx-text2, #9590b0);
  transition: transform .2s;
}
.wx-model-header-arrow.wx-expanded { transform: rotate(90deg); }
.wx-model-body {
  display: none; padding: 10px 12px;
  border-top: 1px solid var(--wx-border, rgba(140,130,200,.2));
}
.wx-model-body.wx-show { display: block; }

/* 自动切换开关 */
.wx-auto-switch {
  display: flex; align-items: center; gap: 10px;
  padding: 10px 12px; margin-bottom: 10px;
  border: 1px solid var(--wx-border, rgba(140,130,200,.2));
  border-radius: 10px; background: rgba(255,255,255,.03);
}
.wx-auto-switch label {
  font-size: .84em; font-weight: 500;
  color: var(--wx-text, #d8d4e8);
  flex: 1;
}
.wx-toggle {
  position: relative; width: 40px; height: 22px;
  background: rgba(255,255,255,.15); border-radius: 11px;
  cursor: pointer; transition: background .2s;
  border: none;
}
.wx-toggle.wx-on { background: rgba(72,187,120,.6); }
.wx-toggle::after {
  content: ''; position: absolute;
  width: 18px; height: 18px; border-radius: 50%;
  background: #fff; top: 2px; left: 2px;
  transition: left .2s;
}
.wx-toggle.wx-on::after { left: 20px; }

/* 空状态 */
.wx-empty {
  padding: 20px 10px; text-align: center;
  font-size: .83em; color: var(--wx-text2, #9590b0);
  opacity: .8;
}

/* 编辑子面板 */
.wx-sub-panel {
  border: 1px solid var(--wx-border, rgba(140,130,200,.2));
  border-radius: 10px; padding: 14px;
  background: rgba(0,0,0,.18); margin-top: 10px;
}
.wx-sub-title {
  font-size: .82em; font-weight: 600;
  color: var(--wx-text, #d8d4e8);
  margin-bottom: 12px;
  display: flex; align-items: center; gap: 8px;
}

/* 展开收起prompt */
.wx-prompt-toggle {
  background: none; border: none; cursor: pointer;
  font-size: .74em; color: var(--wx-accent, #a78bfa);
  padding: 2px 0; text-decoration: underline; text-underline-offset: 2px;
}
.wx-prompt-block { display: none; margin-top: 6px; }
.wx-prompt-block.wx-show { display: block; }

/* 底部 */
.wx-footer {
  padding: 10px 16px;
  border-top: 1px solid var(--wx-border, rgba(140,130,200,.2));
  display: flex; justify-content: flex-end; gap: 8px;
  flex-shrink: 0; background: rgba(0,0,0,.1);
}

/* ── 🌙 夜间模式（蓝紫塔罗牌主题，固定色值不跟随酒馆） ── */
#wx-panel {
  --wx-bg: #161225;
  --wx-bg2: rgba(130,120,200,.08);
  --wx-bg3: rgba(130,120,200,.15);
  --wx-text: #d8d4e8;
  --wx-text2: #9590b0;
  --wx-border: rgba(140,130,200,.2);
  --wx-accent: #a78bfa;
  --wx-input-bg: rgba(0,0,0,.3);
}
/* ── ☀️ 白天模式（羊皮纸主题） ── */
#wx-panel.wx-day {
  --wx-bg: #f0e6d2;
  --wx-bg2: rgba(120,90,50,.08);
  --wx-bg3: rgba(120,90,50,.14);
  --wx-text: #3d3427;
  --wx-text2: #7a6e5d;
  --wx-border: rgba(120,90,50,.2);
  --wx-accent: #8b6914;
  --wx-input-bg: rgba(255,255,255,.5);
}
#wx-panel.wx-day { background: var(--wx-bg); color: var(--wx-text); box-shadow: 0 16px 48px rgba(80,60,20,.25); }
#wx-panel.wx-day .wx-header { background: rgba(120,90,50,.04); border-bottom-color: var(--wx-border); }
#wx-panel.wx-day .wx-header-title { color: var(--wx-text); }
#wx-panel.wx-day .wx-close { color: var(--wx-text2); }
#wx-panel.wx-day .wx-close:hover { background: rgba(120,90,50,.08); }
#wx-panel.wx-day .wx-tab { color: var(--wx-text2); }
#wx-panel.wx-day .wx-tab:hover { color: var(--wx-text); background: rgba(120,90,50,.06); }
#wx-panel.wx-day .wx-tab.wx-active { color: var(--wx-accent); border-bottom-color: var(--wx-accent); background: rgba(139,105,20,.1); }
#wx-panel.wx-day .wx-tabs { border-bottom-color: var(--wx-border); }
#wx-panel.wx-day .wx-body::-webkit-scrollbar-thumb { background: rgba(120,90,50,.15); }
#wx-panel.wx-day .wx-profile-item { border-color: var(--wx-border); background: var(--wx-bg2); }
#wx-panel.wx-day .wx-profile-item:hover { background: var(--wx-bg3); }
#wx-panel.wx-day .wx-profile-name { color: var(--wx-text); }
#wx-panel.wx-day .wx-profile-meta { color: var(--wx-text2); }
#wx-panel.wx-day .wx-btn { border-color: var(--wx-border); background: var(--wx-bg2); color: var(--wx-text); }
#wx-panel.wx-day .wx-btn:hover { background: var(--wx-bg3); }
#wx-panel.wx-day .wx-input, #wx-panel.wx-day .wx-textarea { background: var(--wx-input-bg); border-color: var(--wx-border); color: var(--wx-text); }
#wx-panel.wx-day .wx-label { color: var(--wx-text2); }
#wx-panel.wx-day .wx-settings-section { border-color: var(--wx-border); }
#wx-panel.wx-day .wx-settings-title { color: var(--wx-accent); }
#wx-panel.wx-day .wx-model-section { border-color: var(--wx-border); }
#wx-panel.wx-day .wx-model-header { background: var(--wx-bg2); }
#wx-panel.wx-day .wx-model-header:hover { background: var(--wx-bg3); }
#wx-panel.wx-day .wx-model-header-left { color: var(--wx-text); }
#wx-panel.wx-day .wx-model-body { border-top-color: var(--wx-border); }
#wx-panel.wx-day .wx-auto-switch { border-color: var(--wx-border); background: var(--wx-bg2); }
#wx-panel.wx-day .wx-auto-switch label { color: var(--wx-text); }
#wx-panel.wx-day .wx-sub-panel { border-color: var(--wx-border); background: rgba(120,90,50,.04); }
#wx-panel.wx-day .wx-sub-title { color: var(--wx-text); }
#wx-panel.wx-day .wx-divider::before { border-top-color: var(--wx-border); }
#wx-panel.wx-day .wx-divider span { background: var(--wx-bg); color: var(--wx-text2); }
#wx-panel.wx-day .wx-footer { border-top-color: var(--wx-border); background: rgba(120,90,50,.04); }
#wx-panel.wx-day .wx-empty { color: var(--wx-text2); }
#wx-panel.wx-day .wx-option-btn { border-color: var(--wx-border); background: var(--wx-bg2); color: var(--wx-text2); }
#wx-panel.wx-day .wx-option-btn:hover { background: var(--wx-bg3); color: var(--wx-text); }
#wx-panel.wx-day .wx-option-btn.wx-selected { background: rgba(139,105,20,.12); border-color: var(--wx-accent); color: var(--wx-accent); }

/* 主题切换按钮 */
.wx-theme-toggle {
  background: none; border: 1px solid var(--wx-border, rgba(255,255,255,.12));
  border-radius: 8px; cursor: pointer; font-size: 1.1em;
  padding: 3px 8px; transition: all .15s;
  color: var(--wx-text2, #8a8fa8);
  margin-right: 6px;
}
.wx-theme-toggle:hover { background: var(--wx-bg3, rgba(255,255,255,.1)); }

/* 快捷指令 */
.wx-qc-group { margin-bottom: 12px; }
.wx-qc-group-header {
  display: flex; align-items: center; gap: 6px; margin-bottom: 6px;
}
.wx-qc-group-title {
  font-size: 12px; font-weight: 600;
  color: var(--wx-accent, #7db5f0);
  letter-spacing: .5px;
}
.wx-qc-add-btn {
  width: 20px; height: 20px; border-radius: 50%;
  border: 1px dashed var(--wx-border, rgba(255,255,255,.2));
  background: transparent; color: var(--wx-text2, #8a8fa8);
  font-size: 14px; cursor: pointer; display: flex;
  align-items: center; justify-content: center; line-height: 1;
  transition: all .15s;
}
.wx-qc-add-btn:hover { border-color: var(--wx-accent, #7db5f0); color: var(--wx-accent, #7db5f0); background: var(--wx-bg2, rgba(255,255,255,.05)); }
.wx-qc-list { display: flex; flex-wrap: wrap; gap: 8px; }
.wx-qc-btn {
  padding: 8px 14px; border: 1px solid var(--wx-border, rgba(255,255,255,.15));
  background: var(--wx-bg2, rgba(255,255,255,.05));
  color: var(--wx-text, #e0e2ea); border-radius: 7px;
  cursor: pointer; font-size: 14px; white-space: nowrap;
  transition: background .15s, border-color .15s;
}
.wx-qc-btn:hover { background: var(--wx-bg3, rgba(255,255,255,.1)); border-color: var(--wx-accent, #7db5f0); }

/* 一键切默认预设（首页顶部） */
.wx-preset-jump {
  padding-bottom: 14px; margin-bottom: 14px;
  border-bottom: 1px dashed var(--wx-border, rgba(140,130,200,.35));
}
.wx-pj-btn {
  font-weight: 600; color: #fff !important; border: none !important;
  flex: 1; text-align: center; min-width: 0;
}
.wx-pj-btn:hover { filter: brightness(1.18); }
.wx-pj-claude { background: linear-gradient(135deg, #c96342, #a34a2e) !important; }
.wx-pj-gemini { background: linear-gradient(135deg, #4e8cff, #3367d6) !important; }
.wx-pj-glm    { background: linear-gradient(135deg, #2bb673, #1d8f57) !important; }
.wx-pj-ds     { background: linear-gradient(135deg, #5b6cff, #3f4ed8) !important; }
.wx-preset-jump .wx-qc-list { flex-wrap: nowrap; }
.wx-qc-floor-row {
  display: flex; align-items: center; gap: 8px; margin-top: 2px;
}
.wx-qc-floor-btn {
  padding: 8px 14px; border: 1px solid var(--wx-border, rgba(255,255,255,.15));
  background: var(--wx-bg2, rgba(255,255,255,.05));
  color: var(--wx-text, #e0e2ea); border-radius: 6px;
  cursor: pointer; font-size: 14px; border-radius: 7px; transition: background .15s;
}
.wx-qc-floor-btn:hover { background: var(--wx-bg3, rgba(255,255,255,.1)); }

/* 编辑指令折叠区 */
.wx-qc-editor-toggle {
  display: flex; align-items: center; gap: 6px;
  margin-top: 10px; padding: 6px 0; cursor: pointer;
  border: none; background: none;
  color: var(--wx-accent, #7db5f0); font-size: 12px; font-weight: 500;
}
.wx-qc-editor-toggle:hover { text-decoration: underline; }
.wx-qc-editor {
  display: none; margin-top: 8px;
  border: 1px solid var(--wx-border, rgba(255,255,255,.1));
  border-radius: 8px; padding: 10px; max-height: 360px; overflow-y: auto;
}
.wx-qc-editor.wx-open { display: block; }
.wx-qc-editor-group { margin-bottom: 10px; }
.wx-qc-editor-group:last-child { margin-bottom: 0; }
.wx-qc-editor-label {
