        if (typeof imported.archivePromptFormat === 'string') {
          s.archivePromptFormat = imported.archivePromptFormat; count++;
        }
        if (typeof imported.archiveCompressRequire === 'string') {
          s.archiveCompressRequire = imported.archiveCompressRequire; count++;
        }
        // 总结设置
