// ── 事件监听 ─────────────────────────────────────────────────
// ══════════════════════════════════════════════════════════════

// 按钮
const btnEvent = getButtonEvent(BUTTON_NAME);
eventOn(btnEvent, () => {
  isPanelVisible() ? hidePanel() : showPanel();
});

// API模型变更时自动切换
eventOn(tavern_events.CHATCOMPLETION_MODEL_CHANGED, async model => {
  applyModelBodyParams(model);
  applyStartReplyMemory(model);
  await autoSwitchByModel(model);
});

// AI 回复时：检测阈值 + 捕获总结结果
eventOn(tavern_events.MESSAGE_RECEIVED, (messageId) => {
  // 如果正在总结，捕获结果
  onMessageReceived(messageId);
  // 否则检查阈值
  if (!archiveState) {
    setTimeout(() => checkThreshold(), 1000);
  }
});

// 消息删除/编辑时：如果在 generating 状态就重置（防止用户删掉总结请求后状态残留）
eventOn(tavern_events.MESSAGE_DELETED, () => {
  if (archiveState === 'generating') {
    console.log('[美梦巡游·归档] 检测到消息删除，重置 generating 状态');
    restoreFromSnapshot();
  }
});

// 聊天切换时：动态跟随 + 阈值检查
eventOn(tavern_events.CHAT_CHANGED, () => {
  setTimeout(() => dynamicFollowOnChatChange(), 500);
  setTimeout(() => checkThreshold(), 1500); // 切聊天/刷新后也检查归档阈值
});

// 首次加载：注入 CSS + 动态跟随 + 阈值检查
injectStyle(); // 提前注入，确保 toast/弹窗的 mobile CSS 生效
setTimeout(() => dynamicFollowOnChatChange(), 2000);
setTimeout(() => checkThreshold(), 3000); // 首次加载也检查一次
setTimeout(() => applyModelBodyParams(), 2500); // 首次加载按当前模型校正附加参数
setTimeout(() => { try {
  const model = currentModelName();
  applyStartReplyMemory(model, true); // 刷新后按当前API来源读取模型。
} catch(e){} }, 2600);


// 页面卸载清理
$(window).on('pagehide', () => {
  if (panelEl) { panelEl.remove(); panelEl = null; }
  const s = document.getElementById('wx-style');
  if (s) s.remove();
});

// ── 推理设置：幂等检查（已正确则跳过，否则修正） ──
(function ensureReasoningSettings() {
  setTimeout(() => {
    try {
      const ctx = mctx();
      const pu = ctx && ctx.powerUserSettings;
      if (!pu || !pu.reasoning) return;
      // 手动设成 thinking/think 系标签的,视为有意为之(DS官方尾部需要),不覆盖
      const cur = String(pu.reasoning.prefix || '');
      if (cur === '<thinking>' || cur === '<think>') {
        if (!pu.reasoning.auto_parse) {
          pu.reasoning.auto_parse = true;
          if (ctx.saveSettingsDebounced) ctx.saveSettingsDebounced();
        }
        console.log('[美梦巡游] 检测到 ' + cur + ' 解析设置,保持不动');
        return;
      }
      const want = { prefix: '<parade>', suffix: '</parade>', auto_parse: true };
      let changed = false;
      Object.keys(want).forEach(k => {
        if (pu.reasoning[k] !== want[k]) { pu.reasoning[k] = want[k]; changed = true; }
      });
      if (changed) {
        const jq = mjq();
        jq('#reasoning_prefix').val(want.prefix);
        jq('#reasoning_suffix').val(want.suffix);
        jq('#reasoning_auto_parse').prop('checked', true);
        if (ctx.saveSettingsDebounced) ctx.saveSettingsDebounced();
        console.log('[美梦巡游] 推理设置已修正为 parade');
      } else {
        console.log('[美梦巡游] 推理设置已就绪');
      }
    } catch(e) {
      console.warn('[美梦巡游] 推理设置检查失败', e);
    }
  }, 1500);
})();

console.log('[美梦巡游] 已加载（含自动大总结模块）');

})();
